INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_289cea76dd658a0dbc32a5ac","wiki/sources/handbuch-40820-inb-2026-data.md",290,"Seite 257","Richtlinie\n\nBahnbetrieb Fahrdienstvorschrift\n\nRangieren; Allgemeines 408.4811\n\nSeite 1\n\n1 Tf, Rb\n\nIn der Regel rangiert der Tf. In Ã¶rtlichen ZusÃ¤tzen oder in einer Betra dÃ¼rfen Auf- Aufgaben\n\ngaben des Tf einem Rb Ã¼bertragen sein. Der Tf darf Aufgaben einem Rb Ã¼bertra- Ã¼bertragen\n\ngen.\n\n2 Besetzen der Triebfahrzeuge\n\nArbeitende Triebfahrzeuge mÃ¼ssen beim Rangieren mit einem Tf besetzt sein. Arbeitende\n\nMuss der Tf Fahrweg und Signale beobachten, muss er sich bei Triebfahrzeugen Triebfahrzeumit zwei FÃ¼hrerrÃ¤umen im vorderen FÃ¼hrerraum aufhalten. Sind arbeitende Trieb- ge besetzen\n\nfahrzeuge gesteuert, dÃ¼rfen sie unbesetzt sein.\n\n3 VerstÃ¤ndigen\n\n(1) Es gilt Folgendes:\n\na) MÃ¼ndliche AuftrÃ¤ge und Meldungen mÃ¼ssen vom EmpfÃ¤nger wiederholt Allgemeines\n\nwerden. Die Wiederholung muss alle wesentlichen Angaben enthalten.\n\nb) Bei fernmÃ¼ndlicher VerstÃ¤ndigung, muss jedes Wiederholen mit den Worten â€žIch wiederholeâ€œ eingeleitet werden.\n\nc) Die Richtigkeit der Wiederholung ist vom Mitarbeiter, der den Auftrag oder\n\ndie Meldung gegeben hat, mit dem Wort â€žRichtigâ€œ zu bestÃ¤tigen.\n\n(2) AuftrÃ¤ge oder Meldungen Ã¼ber einseitig gerichtete Sprecheinrichtungen mÃ¼s- Einseitig gesen zweimal gegeben werden. Die zweite Durchsage ist mit den Worten â€žIch richtete\n\nwiederholeâ€œ einzuleiten. Sprecheinrichtungen\n\n(3) Bei Fragen mÃ¼ssen in der Antwort alle wesentlichen Angaben der Frage ent- Fragen\n\nhalten sein.\n\n(4) Die Regeln fÃ¼r die VerstÃ¤ndigung Ã¼ber Rangierfunk sind in der Richtlinie 481 Rangierfunk\n\ngegeben.\n\n(5) AuftrÃ¤ge, Fahrzeugbewegungen auszufÃ¼hren, darf der Rb nur erteilen, wenn AuftrÃ¤ge\n\ner nach Ril 408.4814 Abschnitt 4 Absatz (1) den Fahrweg beobachtet. AuftrÃ¤ge zum Halten muss der Tf stets ausfÃ¼hren, auch wenn sie nicht vom Rb gegeben werden.",243,"{\"canonical_url\":null,\"normalized_sha256\":\"edab5f2a2db9d7108c56fdcc27740b3e32579b846270e1e2e3fcddbf2e7d2dc6\",\"page\":257,\"source_id\":\"src_289a2864d8d21dcf1d64\",\"source_sha256\":\"f38027bfed6f5a919e6ab9ab34b4ddbbcc9a96bf04cb3baa79fb90e01b0ca248\",\"source_version_id\":\"sv_0ce2100159de2983ba7601f0\"}","912cada53d7bb984f75af8eac373009c9f0034a2c749a07f7a61366f89fea583"],["chunk_13703eac24b09fe3d4e9711b","wiki/sources/handbuch-40820-inb-2026-data.md",291,"Seite 257","(6) Wenn der Rb den Fahrauftrag nicht Ã¼ber Rangierfunk erteilt, muss er mit dem WÃ¤hrend der\n\nTf eine Rangierseite vereinbaren, sofern sie nicht in Ã¶rtlichen ZusÃ¤tzen be- Fahrt\n\nstimmt ist.\n\nWird die Sichtverbindung zwischen Tf und Rb unterbrochen, muss der Tf die\n\nGeschwindigkeit ermÃ¤ÃŸigen, wird die Sichtverbindung nicht alsbald wieder\n\nhergestellt, muss der Tf anhalten.\n\nWird dem Tf die Aufnahme der Rangiersignale erschwert, muss der Rb einen\n\noder mehrere Rangierer zur Weitergabe der Signale bestimmen.\n\n4 Rangieren in Ortsstellbereichen\n\nBesonderheiten\n\nFachautor: I.IBB 31; Dietmar Homeyer; [E-Mail-Adresse entfernt] GÃ¼ltig ab: 14.12.2025",90,"{\"canonical_url\":null,\"normalized_sha256\":\"edab5f2a2db9d7108c56fdcc27740b3e32579b846270e1e2e3fcddbf2e7d2dc6\",\"page\":257,\"source_id\":\"src_289a2864d8d21dcf1d64\",\"source_sha256\":\"f38027bfed6f5a919e6ab9ab34b4ddbbcc9a96bf04cb3baa79fb90e01b0ca248\",\"source_version_id\":\"sv_0ce2100159de2983ba7601f0\"}","a0ef4a7d993e7d826b30068f02a45d1a95c7ddd8df54d9b455a4167e4aaa2348"],["chunk_15baed213d32076351ae62e8","wiki/sources/handbuch-40820-inb-2026-data.md",292,"Seite 258","Rangieren; Allgemeines 408.4811\n\nSeite 2\n\n(1) Besonderheiten (z. B. gestÃ¶rte BahnÃ¼bergangssicherung, niedrigere Geschwindigkeit als 25 km/h) sind dem Tf von der in Absatz (3) a) genannten\n\nStelle bekanntzugeben.\n\nBesonderhei- (2) Besonderheiten dÃ¼rfen von der Bekanntgabe ausgenommen werden, wenn:\n\nten bekannt\n\n- Gleise mit abgeschalteter oder gestÃ¶rter Oberleitung mit Fahrleitungssignageben\n\nlen oder\n\n- Besonderheiten in Gleisen, z.B. durch WÃ¤rterhaltscheiben\n\ngekennzeichnet sind.\n\nZustÃ¤ndige (3) Es gilt Folgendes:\n\nStelle\n\na) Bevor der Tf in einen Ortsstellbereich hineinfÃ¤hrt, muss er sich bei der zustÃ¤ndigen Stelle melden oder Unterlagen einsehen. Die zustÃ¤ndige Stelle\n\nbzw. die Unterlagen werden in Ã¶rtlichen ZusÃ¤tzen genannt.\n\nb) Bei Arbeitsaufnahme oder nach einer Arbeitsunterbrechung in einem Ortsstellbereich muss sich der Tf bei der zustÃ¤ndigen Stelle melden oder Unterlagen einsehen (Ã¶rtliche ZusÃ¤tze). Die zustÃ¤ndige Stelle bzw. die Unterlagen werden in Ã¶rtlichen ZusÃ¤tzen genannt.\n\nUnregelmÃ¤- (4) Der Tf muss UnregelmÃ¤ÃŸigkeiten an Bahnanlagen und Fahrzeugen an die in\n\nÃŸigkeiten Ã¶rtlichen ZusÃ¤tzen genannte zustÃ¤ndige Stelle melden.\n\nZusÃ¤tzliche (5) In Ã¶rtlichen ZusÃ¤tzen kÃ¶nnen zusÃ¤tzliche Regeln gegeben sein, z.B. Be-\n\nRegeln schreibung des Ortsstellbereiches, dessen Grenzen und weitere Ã¶rtliche Regeln.\n\n5 Verhalten bei Gefahr oder UnregelmÃ¤ÃŸigkeiten\n\nGefahr (1) Wenn eine Gefahr droht, muss in eigener Verantwortung umsichtig und entschlossen alles getan werden, um die Gefahr abzuwenden oder zu mindern.\n\nBei Gefahr mÃ¼ssen Fahrzeuge angehalten werden, soweit nicht die Gefahr\n\ndurch das Anhalten vergrÃ¶ÃŸert wird. Eine Gefahr muss auch fÃ¼r Nachbargleise angenommen werden, wenn nicht einwandfrei festgestellt wird, dass die\n\nNachbargleise befahren werden kÃ¶nnen.",236,"{\"canonical_url\":null,\"normalized_sha256\":\"edab5f2a2db9d7108c56fdcc27740b3e32579b846270e1e2e3fcddbf2e7d2dc6\",\"page\":258,\"source_id\":\"src_289a2864d8d21dcf1d64\",\"source_sha2