INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_66d9c1afff73e769ccece7f3","wiki/sources/inb-2027-anlage-1-0-data.md",6,"Seite 5","AbkÃ¼rzung Bezeichnung\n\nVDV Verband Deutscher Verkehrsunternehmen\n\nVU VerspÃ¤tungsursachen\n\nZB Zugangsberechtigter\n\nAnlage 1.0 zu den Infrastrukturnutzungsbedingungen der DB InfraGO AG 2027\n\n-AbkÃ¼rzungsverzeichnis - GÃ¼ltig ab 13.12.2026\n\nRedaktionsstand: 14.12.2025 Seite 5 von 5",31,"{\"canonical_url\":null,\"normalized_sha256\":\"9e83f3c7c24824212709131a1f51d66205a0f400bec58d409e5d3cc41093b8c0\",\"page\":5,\"source_id\":\"src_9bbddbc6001574ece974\",\"source_sha256\":\"eff3c636e2dc1195e2fb852d3e2ef565c9ba1d695c40023c689d51ed0e27b2ca\",\"source_version_id\":\"sv_1f9b220327b2209be36c1413\"}","c76e07503499f1be5a430ad4ed99bf56285d5dab8c0f80e7ef7e490837f7f68d"],["chunk_f61f0fec11b10fb66c816fa3","wiki/sources/inb-2027-anlage-2-3-10-data.md",0,"Seite 1","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG DB InfraGO AG 2027\n\nNutzungsbedingungen ETCS Seite 1 von 13\n\n(1) Einleitung\n\nUm Fahrzeugen Fahrten im ETCS Level 2 zu ermÃ¶glichen, mÃ¼ssen ETCS-FahrzeuggerÃ¤te (OBU)\n\nund ETCS-Zentralen (RBC) verschlÃ¼sselt kommunizieren kÃ¶nnen. Hierzu werden entsprechende\n\nkryptografische SchlÃ¼ssel (KMAC) sowie eine eindeutige ETCS-Kennung (NID-ENGINE) des Fahrzeugs benÃ¶tigt, die auf der OBU und auf dem RBC installiert werden mÃ¼ssen. Die DB InfraGO AG\n\nbetreibt hierzu ein Key Management Center (KMC DB) bei dem EVU-Unternehmen die SchlÃ¼ssel\n\nfÃ¼r DB InfraGO AG Strecken beantragen kÃ¶nnen. FÃ¼r den Datenaustausch mit dem KMC DB ist die\n\nE-Mail-Adresse\n\n[E-Mail-Adresse entfernt]\n\nzu verwenden.\n\nUnter einem Key Management Center (KMC) versteht man eine technische Datenbank, die geeignet ist, alle funktionalen und kryptografischen Anforderungen des UNISIG SUBSET-038 (aus Beschluss der Kommission vom 27.05.2016 (2016/919/EU) zur Ã„nderung des Beschlusses\n\n2012/696/EU Ã¼ber die Technische Spezifikation fÃ¼r die InteroperabilitÃ¤t der Teilsysteme â€žZugsteuerung, Zugsicherung und Signalgebungâ€œ des transeuropÃ¤ischen Eisenbahnsystems) sowie der dort\n\ngenannten normativen Referenzen, zu erfÃ¼llen. Daraus folgt, dass das KMC insbesondere folgenden weiteren Anforderungen genÃ¼gen muss:\n\nâ€¢ UNISIG EURORADIO FIS Subset-037 (aus Beschluss 2016/919/EU)\n\nâ€¢ ANSI X9.52 â€“ 1998 Triple Data Encryption Algorithm Modes of Operation\n\nâ€¢ ANSI X3.92 â€“ 1981 Data Encryption Standard (DES) Algorithm\n\nSofern das KMC die Spezifikationen der ETCS Baseline 3 Release 2 und GSM-R Baseline 1 erfÃ¼llt,\n\nist auch\n\nâ€¢ UNISIG Online Key Management FFFIS Subset-137 (aus Beschluss 2016/919/EU)\n\nerforderlich.",231,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":1,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","3336be2d66b42c5b193fcd1b2d126f298ae0a892e9014839f287ee8c49ed8636"],["chunk_80ea9a28cca444eae5504489","wiki/sources/inb-2027-anlage-2-3-10-data.md",1,"Seite 1","Das KMC dient der sicheren Aufbewahrung und Verwaltung der an das Eisenbahnverkehrsunternehmen (EVU) Ã¼bergebenen FahrzeugschlÃ¼ssel, so dass diese im Bedarfsfall (zum Beispiel nach\n\nWartungsarbeiten) wieder im Fahrzeug installiert werden kÃ¶nnen, sowie der standardisierten Kommunikation mit anderen KMCs Ã¼ber eine festgelegte E-Mail Adresse bzw. Ã¼ber die Onlineschnittstelle gemÃ¤ÃŸ Subset-137.\n\nUnter EVU wird in diesem Anhang auch ein Fahrzeughalter ohne Zulassung als EVU verstanden,\n\nda er bezÃ¼glich der Inhalte dieses Anhangs gleichgestellt ist.\n\nSteht dem EVU kein eigenes KMC zur VerfÃ¼gung, kann dieses seine Fahrzeuge Ã¼ber ein KMC Dritter verwalten lassen. In diesem Fall muss dieses KMC bei dem KMC DB registriert werden. Es besteht ebenfalls die MÃ¶glichkeit die Verwaltung der Fahrzeuge gegen Entgelt durch die DB InfraGO\n\nAG durchfÃ¼hren zu lassen, siehe hierzu Kapitel 4 - Ablauf â€žVerwaltung von ETCS-\n\nFahrzeuggerÃ¤tenâ€œ. Dabei muss das beauftragte KMC die Offlineschnittstelle nach Subset-038 unterstÃ¼tzen. Das Onlineverfahren zum SchlÃ¼sselaustausch kann alternativ verwendet werden, wenn\n\ndies von allen beteiligten KMC unterstÃ¼tzt wird, eine Public Key Infrastructure (PKI) gegeben ist und\n\ndiese den Vorgaben des Subset-137 entspricht.\n\nDamit die DB InfraGO AG ETCS-StÃ¶rfÃ¤lle analysieren und bewerten kann, sind neben den streckenseitigen technischen Daten ggf. auch Fahrzeugdaten notwendig. Diese werden dann entspre-\n\nGÃ¼ltig ab: 13.12.2026",197,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":1,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","7c1082c29765d656b0f7b541555790f9a4ea0ae9f33e0907f5cccabdd18fd4de"],["chunk_5f0e3641fca1e653578020d7","wiki/sources/inb-2027-anlage-2-3-10-data.md",2,"Seite 2","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG 2027\n\nNutzungsbedingungen ETCS Seite 2 von 13\n\nchend Â§12 durch die DB InfraGO AG angefordert. Die DB InfraGO AG wird ihrerseits ebenfalls Infrastrukturdaten zur Analyse von FahrzeugstÃ¶rungen entsprechend Â§13 bereitstellen.\n\nDie Mitwirkung aller Beteiligten ist in solchen FÃ¤llen unbedingt erforderlich.\n\nDie entsprechenden Verfahrensweisen werden in diesem Anhang festgelegt und dienen dem geregelten Austausch der Informationen zwischen den EVU und dem Infrastrukturbetreiber.\n\n(2) Ablauf â€žKMC registrierenâ€œ\n\nMit dem Antrag â€žKMC registrierenâ€œ kann ein EVU oder ein Infrastrukturbetreiber (EIU) sein KMC\n\nbeim KMC DB registrieren. Nur wenn dies erfolgt ist, kÃ¶nnen SchlÃ¼ssel fÃ¼r die Kommunikation zwischen OBUs und RBCs der DB InfraGO AG beantragt werden.\n\nIn diesem Antrag sind die Daten des KMC wie Name und E-Mail-Adresse sowie die Daten des Antragstellers anzugeben. Alle folgenden SchlÃ¼sselantrÃ¤ge mÃ¼ssen dem hier angegebenen KMC zugeordnet werden und werden nur von der angegebenen E-Mail-Adresse akzeptiert. FÃ¼r die Kommunikation bzw. den Austausch der Subset-038 Nachrichten zwischen dem KMC DB und dem KMC\n\ndes Kunden wird ein kryptografischer SchlÃ¼ssel (K-KMC) benÃ¶tigt. Dieser wird mit der Antragsbearbeitung generiert und verteilt. Dieser SchlÃ¼ssel darf nicht unverschlÃ¼sselt versendet werden und\n\nmuss sicher auf dem KMC des Kunden gespeichert werden (weitere Informationen siehe Kapitel 4).\n\nWird das Onlineverfahren verwendet, so sind Angaben zur genutzten Certificate Authority (CA) und\n\nder Adressierung des KMC anzugeben.\n\nDer Antrag ist an die im Abschnitt 1 genannte E-Mail-Adresse zu senden. Die AntrÃ¤ge werden in der",238,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":2,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","9d131aff2b41c1ec4365f3085a2b9df15baac859c2107ab65ac515fb11c5ec8c"],["chunk_b57e03621f9ac201a01d7b43","wiki/sources/inb-2027-anlage-2-3-10-data.md",3,"Seite 2","Reihenfolge des Eingangs bearbeitet. Die DB InfraGO AG verpflichtet sich den Antrag innerhalb von\n\n4 Wochen zu bearbeiten.\n\n(3) Verteilung der SchlÃ¼ssel (K-KMC)\n\nBei Verwendung des Offlineverfahrens dÃ¼rfen die K-KMC nicht unverschlÃ¼sselt verteilt werden. Zur\n\nVerteilung der K-KMC wird openSSL eingesetzt. Beide Teilnehmer generieren hierzu mit openSSL\n\neinen privaten und einen Ã¶ffentlichen SchlÃ¼ssel und senden den Ã¶ffentlichen SchlÃ¼ssel dem Kommunikationspartner zu. Der K-KMC wird mit diesem SchlÃ¼ssel verschlÃ¼sselt und ausschlieÃŸlich an\n\ndie KMC-E-Mail-Adresse gesendet. Der K-KMC kann nur mit dem privaten SchlÃ¼ssel wieder entschlÃ¼sselt werden.\n\nSteht eine asymmetrische E-Mail-VerschlÃ¼sselung (z.B. PGP) zur VerfÃ¼gung, kann auch diese verwendet werden.\n\nDas zu verwendende Verfahren ist mit der DB InfraGO AG abzustimmen.\n\nWird die Onlineschnittstelle genutzt, so dÃ¼rfen die genutzten Schnittstellenzertifikate eine GÃ¼ltigkeit\n\nvon 4 Jahren nicht Ã¼berschreiten.\n\n(4) Ablauf â€žVerwaltung von ETCS-FahrzeuggerÃ¤tenâ€œ\n\nDie DB InfraGO AG bietet die Verwaltung von kryptografischen ETCS-SchlÃ¼sseln in Form eines Key\n\nManagement Center gemÃ¤ÃŸ INB Ziffer 5.5.8 an, wenn das EVU kein eigenes KMC besitzt. Dieser\n\nService wird aktuell nur mit der Offlineschnittstelle realisiert.\n\nGÃ¼ltig ab: 13.12.2026",170,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":2,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","1892b95a2ec0b9b76153e001cc96afcf78c302fafdc93d3beae985b9d314bb68"],["chunk_b8ebbdc2cfd9860d43191ffe","wiki/sources/inb-2027-anlage-2-3-10-data.md",4,"Seite 3","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG 2027\n\nNutzungsbedingungen ETCS Seite 3 von 13\n\nUm OBUs bei der DB InfraGO AG zu registrieren, kann, nach der Beauftragung, der Antrag â€žOBU\n\nzuweisenâ€œ verwendet werden. Sobald diese Zuweisung erfolgt ist, kÃ¶nnen die gewÃ¼nschten SchlÃ¼ssel beantragt werden.\n\nFÃ¼r weitere Informationen wenden Sie sich bitte an [E-Mail-Adresse entfernt].\n\n(5) Ablauf â€žSchlÃ¼ssel beantragenâ€œ\n\nIst das KMC des Kunden registriert, kÃ¶nnen SchlÃ¼ssel fÃ¼r die Kommunikation zwischen OBU und\n\nRBC Ã¼ber den Antrag â€žSchlÃ¼ssel beantragenâ€œ beantragt werden. Sollen fÃ¼r eine Strecke mehrere\n\nFahrzeuge eingetragen werden, so kann im Antrag eine Liste der OBUs eingetragen werden.\n\nZusÃ¤tzlich sind die Strecken, auf der die OBU fahren sollen, sowie die gewÃ¼nschte GÃ¼ltigkeitsdauer\n\nanzugeben. Es werden ausschlieÃŸlich SchlÃ¼ssel fÃ¼r DB InfraGO AG Strecken generiert und\n\nausgestellt.\n\nSofern die DB InfraGO AG nicht mit der FÃ¼hrung des KMCs durch das EVU beauftragt wurde, mÃ¼ssen SchlÃ¼ssel fÃ¼r Strecken von anderen EIUs im Ausland direkt dort beantragt werden. Die notwendigen Schritte zum Austausch der SchlÃ¼ssel sind bilateral zu vereinbaren und liegen auÃŸerhalb des\n\nZustÃ¤ndigkeitsbereichs der DB InfraGO AG.\n\nWerden die OBUs von der DB InfraGO AG verwaltet, werden die SchlÃ¼sselantrÃ¤ge an die\n\njeweiligen KMCs weitergeleitet. Liegt eine Strecke dabei auÃŸerhalb des DB InfraGO AG-Bereichs,\n\nsind mit dem Antrag die betroffenen LÃ¤nder anzugeben.\n\nSind die RBCs bekannt, kÃ¶nnen diese zusÃ¤tzlich zur Strecke eingetragen werden. Sind diese nicht\n\nbekannt, ermittelt das KMC DB die notwendigen RBCs aus den Streckenangaben und erstellt die\n\nentsprechenden SchlÃ¼ssel.",241,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":3,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","fe47646f2717adfb9fdcb92370b0e7f65cad9f3eb4d9df13c222786fa4547181"],["chunk_c5dddff54b343c4f24900f19","wiki/sources/inb-2027-anlage-2-3-10-data.md",5,"Seite 3","Die GÃ¼ltigkeitsdauer eines SchlÃ¼ssels ist im Antrag anzugeben, darf jedoch nicht lÃ¤nger als 5 Jahre\n\nsein. Wird ein lÃ¤ngerer Zeitraum angegeben wird die GÃ¼ltigkeitsdauer auf 5 Jahre reduziert. Wird\n\nkein Zeitraum angegeben, beginnt die GÃ¼ltigkeitsdauer von 5 Jahren mit dem Ausstellen des\n\nSchlÃ¼ssels.\n\nLÃ¤uft die GÃ¼ltigkeitsdauer ab, muss der Kunde rechtzeitig einen neuen SchlÃ¼ssel beantragen. Der\n\nSchlÃ¼ssel wird nicht automatisch ersetzt.\n\nDer Antrag ist an die o.g. E-Mail-Adresse zu senden. Die AntrÃ¤ge werden in der Reihenfolge des\n\nEingangs bearbeitet. Die DB InfraGO AG verpflichtet sich die beantragten SchlÃ¼ssel innerhalb von\n\n8 Wochen zur VerfÃ¼gung zu stellen.\n\nIst ein SchlÃ¼ssel an die KMC E-Mail-Adresse des Kunden im Offlineverfahren gesendet worden, ist\n\nder Empfang innerhalb 1 Woche durch den Kunden Ã¼ber die KMC E-Mail-Adresse zu bestÃ¤tigen,\n\nwenn mÃ¶glich mit einer Subset-konformen â€žConfirmation Messageâ€œ. Liegt nach einer Woche keine\n\nBestÃ¤tigung vor, wird der SchlÃ¼ssel automatisch zurÃ¼ckgezogen und kann nicht mehr verwendet\n\nwerden. In diesem Fall wird der Antragsteller Ã¼ber diesen Vorgang via E-Mail informiert.\n\nWerden die SchlÃ¼ssel online Ã¼bertragen, so erfolgt die Quitierung unmittelbar entsprechend der\n\nSchnittstellenspezifikation.\n\nGÃ¼ltig ab: 13.12.2026",177,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":3,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","5286e1d6c9f77b59ebc2c1800c3ffd62f694e42c01cc5310b1b1e1bb7d925c2e"],["chunk_99ce0428e115d52290da1062","wiki/sources/inb-2027-anlage-2-3-10-data.md",6,"Seite 4","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG 2027\n\nNutzungsbedingungen ETCS Seite 4 von 13\n\n(6) Ablauf â€žSchlÃ¼ssel zurÃ¼ckziehenâ€œ\n\nSoll ein SchlÃ¼ssel zurÃ¼ckgezogen werden, ist die entsprechende Subset-Nachricht (â€žDelete Key\n\nRequestâ€œ) an die o.g. E-Mail-Adresse zu senden. Das KMC DB lÃ¶scht daraufhin unwiderruflich den\n\nSchlÃ¼ssel im RBC und im KMC und sendet die Subset konforme â€žConfirmation Messageâ€œ.\n\nBei der Nutzung der Onlineschnittstelle wird die entsprechende Quittung unmittelbar gesendet.\n\n(7) Ablauf â€žOBU lÃ¶schenâ€œ\n\nSofern das DB KMC als EVU KMC fungiert, kann das EVU auch die LÃ¶schung einer ganzen OBU\n\nmit dem Antrag â€œOBU lÃ¶schenâ€ beantragen. Dabei werden dann alle vergebenen SchlÃ¼ssel gelÃ¶scht\n\nund die OBU sebst aus der Datenbank entfernt. Wurden SchlÃ¼ssel von auslÃ¤ndischen EIUs\n\nbereitgestellt, werden diese umgehend informiert, dass die SchlÃ¼ssel nicht weiter verwendet\n\nwerden. Soll eine solche OBU spÃ¤ter wieder in Betrieb genommen werden, wird diese wie ein\n\nNeufahrzeug behandelt (siehe Ablauf 4).\n\n(8) Datensicherheit beim Kunden\n\nNach Erhalt der SchlÃ¼ssel auf dem KMC ist jeder Zugangsberechtigte des Kunden verpflichtet, die\n\nDatensicherheit durch Sicherstellen der ausschlieÃŸlichen Nutzung nur durch befugte Mitarbeiter zu\n\ngewÃ¤hrleisten. SchlÃ¼ssel dÃ¼rfen nur als Anhang zwischen den bekannten KMC-E-Mails verteilt und,\n\nauÃŸer zur OBU bzw. zum RBC, nicht weitergeleitet und nicht in Kopie gesendet werden.\n\nDas EVU bzw. EIU bestÃ¤tigt, dass das gewÃ¤hlte KMC die folgenden Anforderungen zugesichert\n\nhat:\n\nâ–ª UnverschlÃ¼sselte SchlÃ¼ssel werden nur von einer begrenzten Anzahl (in der Regel < 5)\n\nvertrauenswÃ¼rdiger Personen bearbeitet.\n\nâ–ª Diese vertrauenswÃ¼rdigen Personen mÃ¼ssen innerhalb ihrer Organisation explizit benannt\n\nwerden.",245,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":4,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","fde6c715a83177f91c4386c909491aa8134c1fcfa414553b8be6d0adbb0b7ba8"],["chunk_36a38fb5749a0613e937694f","wiki/sources/inb-2027-anlage-2-3-10-data.md",7,"Seite 4","â–ª Die Bearbeitung von SchlÃ¼sseln muss unter Nennung des Bearbeiters dokumentiert werden.\n\nâ–ª Nicht autorisierter Zugang zu SchlÃ¼sseln muss durch geeignete Betriebsprozesse und technische Umgebungen verhindert werden.\n\nâ–ª AuÃŸerhalb der geschÃ¼tzten Umgebung mÃ¼ssen die SchlÃ¼ssel mit Verfahren verschlÃ¼sselt\n\nwerden, die mindestens vergleichbar mit der 3DES VerschlÃ¼sselung der KMC-KMC-\n\nKommunikation sind.\n\nâ–ª Alle SchlÃ¼ssel mÃ¼ssen auf ausfallsicheren elektronischen Speichermedien abgelegt\n\nwerden, die kryptografische gesichert sind. Die dazu verwendeten Verfahren mÃ¼ssen dem\n\naktuellen Stand der VerschlÃ¼sselungstechnik entsprechen.\n\nâ–ª Wird die Onlineschnittstelle nach Subset-137 verwendet, so ist eine PKI mit den dort\n\ndefinierten Verfahren und Standards zu verwenden.\n\nDer Kunde verpflichtet sich den Verlust oder die Kompromittierung eines SchlÃ¼ssels umgehend an\n\ndie o.g. E-Mail Adresse zu melden und den SchlÃ¼ssel zurÃ¼ckziehen zu lassen. Der SchlÃ¼ssel ist\n\numgehend und unwiderruflich auf der OBU zu lÃ¶schen. Die DB InfraGO AG zieht nach\n\nGÃ¼ltig ab: 13.12.2026",140,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":4,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","738210a829ba1cdecc9d83b166d038fd851c168953c89fcb901a3e5d321e3100"],["chunk_6718b690b0a3b0071d3daaba","wiki/sources/inb-2027-anlage-2-3-10-data.md",8,"Seite 5","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG 2027\n\nNutzungsbedingungen ETCS Seite 5 von 13\n\nMeldungseingang umgehend den SchlÃ¼ssel zurÃ¼ck und fordert den Kunden auf, die Einhaltung der\n\noben genannten Vorgaben zu Ã¼berprÃ¼fen.\n\nMeldet ein Kunde mehrfach den Verlust von SchlÃ¼sselmaterial oder zeigt mehrfach die\n\nKompromittierung von SchlÃ¼sseln an, so geht die DB InfraGO AG davon aus, dass die oben\n\ngenannten Vorgaben nicht eingehalten werden. Der Kunde wird dann aufgefordert, einen Audit zur\n\nSchwachstellenanalyse durch die DB InfraGO AG oder durch ein anderes zertifiziertes\n\nUnternehmen fÃ¼r den Security Bereich durchfÃ¼hren zu lassen, um diese Abweichungen\n\naufzudecken und zu beseitigen. Einsteht durch den Verlust oder die Kompromittierung des SchlÃ¼ssels eine unmitterlbare Gefahr fÃ¼r den Betriebsablauf auf dem Streckennetz der DB InfraGO AG,\n\nso ist diese, auch ohne Zustimmung bzw. Information des betroffenen EVU, berechtigt, alle\n\nnotwendigen MaÃŸnahmen zur Gefahrenabwehr zu ergreifen. Eine Gefahr entsteht dann, wenn ein\n\nSchlÃ¼ssel nicht autorisierten Dritten bekannt ist und damit dann dieser Dritte auf die ETCS-FÃ¼hrung\n\ndes Fahrzeuges, fÃ¼r das der SchlÃ¼ssel bereitgestellt wurde, Einfluss nehmen kann. Befindet sich\n\ndas so gefÃ¤hrdete Fahrzeug in Einsatz, so wird von einer unmittelbaren Betriebsgefahr ausgegangen. Die BetriebsfÃ¼hrung der DB InfraGO AG wird dieses Fahrzeug sofort zum Halten bringen oder\n\nan der Weiterfahrt hindern.\n\nBefindet sich das Fahrzeug noch nicht in Benutzung, so wird Ã¼ber die BetriebsfÃ¼hrung der DB InfraGO AG eine Betriebsaufnahme innerhalb der DB Infrastruktur verweigert (keine Fahrerlaubnis",232,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":5,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","1861e6e062f107dd6209e027e4b5b261a2eefde015b21cb4b94dc613cd62a2f6"],["chunk_11a7aaf37a5b28679fb3ca3e","wiki/sources/inb-2027-anlage-2-3-10-data.md",9,"Seite 5","durch Fahrdienstleitung oder ETCS-Zentrale) oder die ÃœberfÃ¼hrung des Fahrzeuges in die DB Infrastruktur wird verwehrt. In solch einem Fall erfolgt dann auch eine unmittelbare Information des\n\nEVUs Ã¼ber die GrÃ¼nde der verwehrten Betriebsaufnahme.\n\nNeben diesen betrieblichen MaÃŸnahmen kann auch durch die LÃ¶schung der betroffenen SchlÃ¼ssel\n\nauf den RBCs eine Betriebsaufnahme technisch verhindert werden.\n\n(9) Zuweisung der ETCS-Kennung (NID-ENGINE)\n\nJede OBU benÃ¶tigt eine eindeutige ETCS-Kennung (NID-ENGINE), die nur einmal vergeben werden darf. Diese wird bei der Anmeldung an den RBC als Identifikation des Fahrzeugs verwendet.\n\nFÃ¼r die Beschaffung dieser Identifikation ist das EVU des Fahrzeugs verantwortlich. Im Regelfall\n\nwird der Hersteller der OBU oder des Fahrzeugs die ETCS-Kennung aus dem zugewiesenen\n\nNummernbereich entnehmen und diese dann mit der OBU bzw. dem Fahrzeug an das EVU Ã¼bergeben.\n\nFalls dem Hersteller kein eigener Nummernbereich zugewiesen wurde oder dieser bereits vollstÃ¤ndig vergeben wurde oder andere GrÃ¼nde eine Zuweisung nicht zulassen, kann ein EVU mit Hauptsitz in der Bundesrepublik Deutschland eine Zuweisung einer ETCS-Kennung durch die DB InfraGO\n\nAG beantragen. Dazu ist ein begrÃ¼ndeter Antrag zu richten an: [E-Mail-Adresse entfernt]\n\nSofern das EVU die Notwendigkeit einer Vergabe der ETCS-Kennung durch die DB InfraGO AG\n\nplausibel machen kann, wird dem EVU die benÃ¶tigte Kennung innerhalb eines Monats nach Beantragung zugewiesen. Das EVU ist verpflichtet alle fÃ¼r die Vergabe und Verwaltung der ETCS-\n\nKennungen notwendigen Daten des jeweiligen Fahrzeugs der DB InfraGO AG mitzuteilen. Die zugewiesene Kennung darf nur auf der entsprechenden OBU verwendet werden.\n\nMissbrÃ¤uchliche Verwendung der Kennungen, insbesondere Mehrfachverwendung, Verwendung",245,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":5,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","d475c669d27aed866fcb4601373cad51844a424a84053ab480dbfcd9b9e7eebb"],["chunk_3ea96786b40e5efac11dc188","wiki/sources/inb-2027-anlage-2-3-10-data.md",10,"Seite 5","auf anderen Fahrzeugen oder OBU als hinterlegt oder Weitergabe an Dritte, sind durch das nutzende EVU zu verhindern.\n\nGÃ¼ltig ab: 13.12.2026",21,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":5,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","528306afb115507e9f2636c69827236533a79c514f99719ef07944c030eacd22"],["chunk_c0ba76e0b53e955cc5d17805","wiki/sources/inb-2027-anlage-2-3-10-data.md",11,"Seite 6","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG 2027\n\nNutzungsbedingungen ETCS Seite 6 von 13\n\nDie DB InfraGO AG ist berechtigt im Falle eines solchen Missbrauch die ETCS-Kennung zurÃ¼ck zu\n\nziehen oder allen betroffenen Fahrzeugen die Nutzung ihrer Infrastruktur zu untersagen.\n\nSpÃ¤testens nach 12 Monaten muss das EVU eine erteilte Inbetriebnahmegenehmigung in einem\n\nMitgliedsstaat der EU als Nachweis der realen Verwendung der ETCS-Kennung vorlegen oder die\n\nETCS-Kennung zurÃ¼ckgeben. Dazu kann ein formloser elektronischer Nachweis per E-Mail an\n\n[E-Mail-Adresse entfernt] gesandt werden.\n\n(10) Verpflichtungen des EVU zum SchlÃ¼sselmanagement\n\nDie verteilten SchlÃ¼ssel dienen zur kryptographischen VerschlÃ¼sselung zwischen RBC und EVC\n\nund schÃ¼tzen vor allem vor einen unberechtigten Zugriff Dritter auf die Kommunikation. Es wird\n\nhierÃ¼ber nicht geregelt, ob ein Fahrzeug bezÃ¼glich seines Zulassungsstands, Eignung und Berechtigung usw. zum sicheren Befahren einer bestimmten Strecke geeignet ist. Dies zu bewerten und im\n\nBedarfsfall sicherzustellen, fÃ¤llt in die Verantwortung des EVU.\n\nDeshalb sind kryptographischen SchlÃ¼ssel, welche von der DB InfraGO AG erstellt und verteilt wurden, nur in Fahrzeugen uneingeschrÃ¤nkt nutzbar, die eine Streckenzulassung fÃ¼r ETCS in Deutschland besitzen.\n\nWurden die SchlÃ¼ssel vom EVU fÃ¼r Fahrzeuge ohne entsprechende Streckenzulassung fÃ¼r ETCS\n\nim ZustÃ¤ndigkeitsbereich der DB InfraGO AG beantragt, so ist folgendes zu beachten:\n\nâ€¢ Bei eingelegten ETCS SIM-Karten ist die Nutzung von ETCS (mit Ausnahme von Test-, Versuchs-, oder Erprobungsfahrten) technisch zu unterbinden.",219,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":6,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","1384753f964a907472e796613a151b87eb535a82d9f911e60232288ef2419361"],["chunk_e88eb15c5aea854af9b01050","wiki/sources/inb-2027-anlage-2-3-10-data.md",12,"Seite 6","â€¢ Die Aktivierung fÃ¼r den Betrieb unter ETCS darf erst zeitnah vor Aufnahme der Test-, Versuchs-, oder Erprobungsfahrten bzw. mit Erteilung der ETCS-Zulassung erfolgen. Ist dies\n\nnicht umsetzbar bzw. der zeitliche Vorlauf nicht einschrÃ¤nkbar, muss die fÃ¼r den Fahrzeugeinsatz zustÃ¤ndige Stelle des EVU sicherstellen, dass mit dem Tfz keine in Betrieb befindlichen ETCS-Strecken der DB InfraGO AG befahren werden, fÃ¼r die bereits SchlÃ¼ssel installiert wurden\n\nâ€¢ Auf Fahrzeugen, auf denen SchlÃ¼ssel nur fÃ¼r Test- oder Zulassungsfahrten aktiviert wurden,\n\nsind diese nach den Fahrten bis zum Erhalt der letztendlichen Zulassung fÃ¼r ETCS in\n\nDeutschland zu lÃ¶schen. Alternativ oder zusÃ¤tzlich kann fÃ¼r ein solches Fahrzeug der Wechsel in die ETCS Ãœberwachung mittels Software- oder Hardwaresperren verhindert werden.\n\nMit dem Erhalt der ETCS SchlÃ¼ssel werden diese Verpflichtungen des EVU anerkannt.\n\n(11) Haftung\n\n1) Die DB InfraGO AG haftet unbeschrÃ¤nkt fÃ¼r Vorsatz und grober FahrlÃ¤ssigkeit.\n\n2) FÃ¼r einfache FahrlÃ¤ssigkeit haftet die DB InfraGO AG - auÃŸer im Falle der Verletzung des Lebens, des KÃ¶rpers oder der Gesundheit - nur, sofern wesentliche Pflichten aus den Bestimmungen\n\ndieses Anhanges (Kardinalpflichten) verletzt werden. Die Haftung ist begrenzt auf den vertragstypischen und vorhersehbaren Schaden.\n\nGÃ¼ltig ab: 13.12.2026",189,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":6,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","0804b6e4eeb36dbe16cc2783ee2996e09f5164b164f08ec91e7db544e697643f"],["chunk_b4c9b2f8e0ccc7914ef5354b","wiki/sources/inb-2027-anlage-2-3-10-data.md",13,"Seite 7","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG 2027\n\nNutzungsbedingungen ETCS Seite 7 von 13\n\n3) Die Haftung fÃ¼r mittelbare und unvorhersehbare SchÃ¤den, Produktions- und Nutzungsausfall,\n\nentgangenen Gewinn, ausgebliebene Einsparungen und VermÃ¶gensschÃ¤den wegen AnsprÃ¼chen\n\nDritter, ist im Falle einfacher FahrlÃ¤ssigkeit - auÃŸer im Falle der Verletzung des Lebens, des KÃ¶rpers oder der Gesundheit - ausgeschlossen.\n\n4) Eine weitergehende Haftung als in den Bestimmungen dieses Anhanges sind - ohne RÃ¼cksicht\n\nauf die Rechtsnatur des geltend gemachten Anspruchs - ausgeschlossen. Vorstehende HaftungsbeschrÃ¤nkungen bzw. -ausschlÃ¼sse gelten jedoch nicht fÃ¼r eine gesetzlich zwingend vorgeschriebene verschuldensabhÃ¤ngige Haftung oder die Haftung aus einer verschuldensabhÃ¤ngigen Garantie.\n\n5) Soweit die Haftung nach Ziffern 2 und 3 ausgeschlossen oder beschrÃ¤nkt ist, gilt dies auch fÃ¼r\n\ndie persÃ¶nliche Haftung der Angestellten, Vertreter, Organe und ErfÃ¼llungsgehilfen der DB InfraGO\n\nAG.\n\n6) Das EVU haftet nach Â§ 278 BGB fÃ¼r SchÃ¤den, die von ihm im Rahmen der SchlÃ¼sselverwaltung\n\n(Home-KMC) eingesetzte Auftragnehmer verursachen.\n\n(12) Allgemeine Mitwirkungsverpflichtung des EVU (gÃ¼ltig fÃ¼r alle ETCS-Level)\n\nETCS als Zugbeeinflussungssystem besteht aus verschiedenen Komponenten, deren komplexes\n\nZusammenwirken erst den Eisenbahnbetrieb ermÃ¶glicht. Hierzu ist auch die korrekte Funktion von\n\nKomponenten erforderlich, auf die die DB InfraGO AG als Infrastrukturbetreiber keinen direkten Einfluss hat. Hierbei sind im Wesentlichen alle ETCS-Anteile auf den Fahrzeugen der Eisenbahnverkehrsunternehmen gemeint.\n\nDas EVU ist fÃ¼r die Handlungssicherheit des Tf fÃ¼r den Fall eines unvorhergesehenen Wechsels",222,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":7,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","8cf0f53fe0e4ef3380de61a4598d1b21fe1e33ca0e10ab1513d2a53e16736fbd"],["chunk_10bfbc29a356e1ef82afc9f1","wiki/sources/inb-2027-anlage-2-3-10-data.md",14,"Seite 7","(Anbieten einer Betriebsart) nach ETCS verantwortlich. Er darf einen Wechsel nach ETCS Level 0,\n\n1, 2 und 3 auf dem DMI nicht bestÃ¤tigen und muss das Tfz gefahrenfrei unmittelbar zum Halten\n\nbringen. Danach setzt er sich unverzÃ¼glich mit dem Fdl in Verbindung.\n\nTreten Beeinflussungen im Bahnbetrieb (z. B. StÃ¶rungen auf den Tfz) auf, so ist das EIU verpflichtet\n\nderen Ursache zu analysieren, deren Sicherheitsrelevanz fÃ¼r den Eisenbahnbetrieb zu bewerten\n\nund ggf. alle notwendigen MaÃŸnahmen zu ergreifen, um Gefahren abzuwenden und den sicheren\n\nEisenbahnbetrieb weiter zu gewÃ¤hrleisten.\n\nWerden zur Analyse Informationen der beteiligten EVU oder technische Daten aus den beteiligten\n\nFahrzeugen (insbesondere JRU-Daten oder andere fahrzeugspezifische Fehleranalysedaten) benÃ¶tigt, so sind die EVU verpflichtet, diese an die DB InfraGO AG zu Ã¼bergeben und bei der Fehleranalyse mitzuwirken, damit die Analyse und Ermittlung der Ursachen der StÃ¶rung erfolgen kann. Hierzu\n\nbenennt das EVU auf Nachfrage ggÃ¼. der ETCS Bauartverantwortung der DB InfraGO AG einen\n\nfachlich kompetenten Ansprechpartner und stellt dessen Kontaktdaten zur VerfÃ¼gung.\n\nDiese Verpflichtungen gelten nicht nur bei sicherheitsrelevanten VorfÃ¤llen, sondern auch bei VorfÃ¤llen, die die VerfÃ¼gbarkeit der Strecke einschrÃ¤nken oder den Bahnbetrieb behindern. Des Weiteren\n\ngelten die Verpflichtungen auch dann, wenn es sich bei dem eingesetzten Tfz um ein seitens des\n\nEVU angemietetes Fahrzeug handelt.\n\nDie Daten mÃ¼ssen in elektronisch lesbarer Form innerhalb von 15 Werktagen nach der Anforderung\n\ndurch die zustÃ¤ndige Bauartverantwortung ETCS unter Angabe des entsprechenden StÃ¶rfalles bereitgestellt werden. Sofern erforderlich, muss auch eine Hilfestellung bei der Interpretation der Da-\n\nGÃ¼ltig ab: 13.12.2026",244,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":7,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","a9684ef1cbe8f990a1c74d12e4589adbfb51845998a33996a039924aad69a33c"],["chunk_c8d3abf452b3eefb35f0f001","wiki/sources/inb-2027-anlage-2-3-10-data.md",15,"Seite 8","Anlage 2.3.10 zu den Infrastrukturnutzungsbedingungen der DB Infra-\n\nGO AG 2027\n\nNutzungsbedingungen ETCS Seite 8 von 13\n\nten durch das EVU bzw. den Fahrzeughersteller erfolgen. Alle Informationen sind an folgende Adresse zu Ã¼bermitteln:\n\n[E-Mail-Adresse entfernt]\n\nSofern die Datenmenge einen Transfer per E-Mail nicht zulÃ¤sst, wird eine andere individuelle Austauschmethode (z. B. ftp) zwischen dem EVU und der DB InfraGO AG vereinbart.\n\nDie DB InfraGO AG verpflichtet sich, alle Informationen vertraulich zu behandeln und diese nur im\n\nRahmen der StÃ¶rungsanalyse zu verwenden. MÃ¼ssen Informationen an Dritte (z. B Infrastrukturhersteller) weitergegeben werden, so wird zuvor das EVU informiert und fÃ¼r den jeweiligen StÃ¶rfall dessen Einwilligung eingeholt.\n\nDen genauen Verfahrensablauf kann dem Ablaufdiagramm unter (17) entnommen werden.\n\n(13) Allgemeine Mitwirkungsverpflichtung der DB InfraGO AG (gÃ¼ltig fÃ¼r alle ETCS-\n\nLevel)\n\nSofern ein EVU zur StÃ¶rungsanalyse auf seinen Fahrzeugen Daten der Infrastrukturkomponenten\n\nder DB InfraGO AG benÃ¶tigt, so kÃ¶nnen diese Ã¼ber die Adresse der Bauartverantwortung ETCS\n\n[E-Mail-Adresse entfernt]\n\nunter Angabe von Zeitpunkt und Ort der Betriebsbeeinflussung, sowie der Fahrzeugidentifikation\n\n(ETCS-ID, MSISDN der beiden EDOR) angefordert werden. FÃ¼r Daten aus einer ETCS-Zentrale\n\nmuss diese ebenfalls mit angegeben werden. Die DB InfraGO AG kann ERTMS-Tracedaten sowie\n\ninterne Tracedaten der ETCS-Zentralen bereitstellen. Die Interpretationstiefe der Daten sowie deren\n\nUmfang ist abhÃ¤ngig vom Hersteller der ETCS-Zentrale und kann sich daher unterscheiden. Hilfestellung zur Interpretation der Informationen kÃ¶nnen durch die DB InfraGO AG nur im Umfang der\n\nInstandhaltungsschulungen des jeweiligen Herstellers geben.",232,"{\"canonical_url\":null,\"normalized_sha256\":\"0ab8f7d25c73972995e4f1348b6282be0af7e0e18691342e54eca62eecfc6265\",\"page\":8,\"source_id\":\"src_8dacb98915f769c6f825\",\"source_sha256\":\"41042fc6ab4ceb9a3155975f2664e3476ea22538c01311120886d196b503d34a\",\"source_version_id\":\"sv_26e90334206b6801aaee95ad\"}","cd8b85ee5656d568304f8586c27e2739578570a8807b845594a2a60cfa09cba4"],["chunk_d6e9132d23612a555cb96e09","wiki/sources/inb-2027-anlage-2-3-10-data.md",16,"Seite 8","Die gelieferten Daten sind vertraulich zu behandeln, dÃ¼rfen an keinen Dritten weitergegeben werden\n\nund sind nur im Rahmen der StÃ¶rungsanalyse zu verwenden.\n\nDie Bauartverantwortung ETCS wird die Anfragen innerhalb von 15 Werktagen beantworten und die\n\nangeforderten Daten in elektronische