INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_f03c0f5fe66547b337fcafbe","wiki/sources/inb-2027-anlage-4-10-data.md",4,"Seite 3","3.5.2 â€žMultiple corridor pathsâ€œ (Korridortrassen, die auf mehreren Korridoren liegen) .... 17\n\n3.5.3 â€žLate Path Requestsâ€œ auf sich Ã¼berschneidenden Abschnitten ................................ 17\n\n3.5.4 Bearbeitung von Anmeldungen .................................................................................... 17\n\n3.5.5 FÃ¼hrendes Tool fÃ¼r â€žLate Path Requestsâ€œ ................................................................... 17\n\n3.5.6 ÃœberprÃ¼fung der AntrÃ¤ge .............................................................................................. 17\n\n3.5.7 Vorbuchung .................................................................................................................... 17\n\n3.5.8 Ausarbeitung der Trasse ............................................................................................... 17\n\n3.5.9 â€žLate Pathâ€œ Angebot (soweit verfÃ¼gbar) ...................................................................... 17\n\n3.6 Phase fÃ¼r ad-hoc AntrÃ¤ge ................................................................................................ 18\n\n3.6.1 KapazitÃ¤tsreserven (â€žReserve Capacityâ€œ (RC)) ........................................................... 18\n\n3.6.2 â€žMultiple corridor pathsâ€œ (Korridortrassen, die auf mehreren Korridoren liegen) .... 18\n\n3.6.3 â€žReserve Capacityâ€œ auf Ã¼berlappenden Abschnitten .................................................. 18\n\n3.6.4 Feeder, Outflow und tailor-made (maÃŸgeschneiderte) Trassen ................................. 18\n\n3.6.5 Bearbeitung des Antrags............................................................................................... 19\n\n3.6.6 FÃ¼hrendes Tool fÃ¼r ad-hoc Anfragen ........................................................................... 19",117,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":3,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","2af6f0e3b093fefc747bd9a4e731431554f16b66862008423c9b27be147e0efe"],["chunk_fcd8e2ea952260ee6344855f","wiki/sources/inb-2027-anlage-4-10-data.md",5,"Seite 3","3.6.7 ÃœberprÃ¼fung der AntrÃ¤ge .............................................................................................. 19\n\n3.6.8 Vorbuchung .................................................................................................................... 19\n\n3.6.9 Ausarbeitung der Trasse ............................................................................................... 19\n\n3.6.10 Ad-hoc Angebot ........................................................................................................... 19\n\n3.7 Antrag auf Ã„nderungen durch den Zugangsberechtigten ............................................. 20\n\n3.7.1 Ã„nderung ........................................................................................................................ 20\n\n3.7.2 RÃ¼cknahme .................................................................................................................... 20\n\n3.7.3 Ãœbertragung von KapazitÃ¤t ........................................................................................... 20\n\n3.7.4 Stornierung .................................................................................................................... 20\n\n3.7.5 Ungenutzte Trassen ....................................................................................................... 20\n\n3.8 AuÃŸergewÃ¶hnliche Transport und Gefahrgut ................................................................. 20\n\n3.8.1 AuÃŸergewÃ¶hnlicher Transport ...................................................................................... 20\n\n3.8.2 Gefahrgut ........................................................................................................................ 20",69,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":3,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","eb6d78d9f9cc9a99f9bace385e8cea71e3f68c00d8237d8ee1d431f921bbf04d"],["chunk_b5c1f9777e3742b257bdf40a","wiki/sources/inb-2027-anlage-4-10-data.md",6,"Seite 3","3.9 Schienenbezogene Dienstleistungen .............................................................................. 21\n\n3.10 Vertragsabschluss und Rechnungsstellung ................................................................. 21\n\n3.11 Beschwerdeverfahren ..................................................................................................... 21\n\n3.12 Ãœbersicht der Fristen ...................................................................................................... 21\n\n3/22",22,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":3,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","d9dcde82812a0517b856c79d292a5784b249c21bc43daeadd4547ffdc57481cb"],["chunk_9486151c26ec720e5879f938","wiki/sources/inb-2027-anlage-4-10-data.md",7,"Seite 4","1 Einleitung\n\nDiese Anlage beschreibt die Verfahren fÃ¼r die KapazitÃ¤tszuweisung durch den Corridor-One-\n\nStop-Shop (C-OSS) eines SchienengÃ¼terverkehrskorridors (Korridor).\n\nHier werden alle Regeln fÃ¼r Zugangsberechtigte, die Nutzung des C-OSS und seiner Produkte -\n\nPre-arranged Paths (PaPs) und KapazitÃ¤tsreserven/Reserve Capacity (RC) - sowie deren\n\nBestellung erlÃ¤utert. Die Prozesse, Bestimmungen und Schritte in Bezug auf PaPs und RC\n\nbeziehen sich auf die Verordnung (EU) Nr. 913/2010 (Verordnung) und sind fÃ¼r alle\n\nZugangsberechtigten gÃ¼ltig. FÃ¼r alle anderen Fragen gelten die entsprechenden Bedingungen,\n\ndie in anderen Teilen der Schienennetz-Benutzungsbedingungen der betreffenden\n\nInfrastrukturbetreiber (IB) / Zuweisungsstelle (Allocation Body (AB)) dargestellt sind.\n\nDiese Anlage wird fÃ¼r jedes Fahrplanjahr Ã¼berarbeitet und aktualisiert. Ã„nderungen der\n\nRechtsgrundlage dieser Anlage (z. B. Ã„nderungen der EU-Verordnungen, des Rahmens fÃ¼r die\n\nKapazitÃ¤tszuweisung oder nationaler Regelwerke) werden bei jeder Ãœberarbeitung umgesetzt.\n\n2 Korridor OSS (C-OSS)\n\nGemÃ¤ÃŸ Artikel 13 der Verordnung hat das Management Board (MB) des Korridors einen C-OSS\n\neingerichtet. Die Aufgaben des C-OSS werden diskriminierungsfrei wahrgenommen und die\n\nVertraulichkeit der Zugangsberechtigte gewahrt.\n\n2.1 Funktion\n\nDer C-OSS ist die einzige Stelle, bei der Zugangsberechtigte dedizierte Fahrplanprodukte fÃ¼r\n\ngrenzÃ¼bergreifende GÃ¼terverkehrskorridore beantragen und erhalten kÃ¶nnen. Die Bearbeitung\n\nder AntrÃ¤ge erfolgt an einem einzigen Ort und in einem einzigen Vorgang. Der C-OSS ist\n\nausschlieÃŸlich fÃ¼r die DurchfÃ¼hrung aller TÃ¤tigkeiten im Zusammenhang mit der VerÃ¶ffentlichung\n\nund Zuweisungsentscheidung in Bezug auf AntrÃ¤ge auf PaPs und RC im Namen der betroffenen\n\nIBs / ABs verantwortlich.",225,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":4,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","00bacb44303cf72b280078ca6b6322c41193def3a83057592a96ac84db249d06"],["chunk_6e8f43966b81e80456ceb1a6","wiki/sources/inb-2027-anlage-4-10-data.md",8,"Seite 4","2.2 Kontakt\n\nDie Kontaktdaten des zustÃ¤ndigen C-OSS sind im Hauptteil dieser INB zu finden.\n\n2.3 Sprache des C-OSS\n\nDie offizielle Sprache des C-OSS fÃ¼r den Schriftverkehr ist Englisch.\n\n2.4 Aufgaben des C-OSS\n\nDas C-OSS fÃ¼hrt die folgenden Aufgaben wÃ¤hrend der folgenden Prozesse aus:\n\nâž¢ Sammlung von internationalen KapazitÃ¤tswÃ¼nschen:\n\no Er befragt alle interessierten Zugangsberechtigten, um die internationalen\n\nKapazitÃ¤tswÃ¼nsche und -bedÃ¼rfnisse fÃ¼r den Jahresfahrplan zu erfassen, indem\n\ner eine Umfrage ausfÃ¼llen lÃ¤sst. Diese Umfrage wird vom C-OSS an die\n\nZugangsberechtigten verschickt und/oder auf der Website des Korridors\n\nverÃ¶ffentlicht. Die Ergebnisse der Umfrage werden in die Vorplanung des PaP-\n\nAngebots einflieÃŸen. Es ist wichtig zu betonen, dass der Korridor unter keinen\n\nUmstÃ¤nden die ErfÃ¼llung aller geÃ¤uÃŸerten KapazitÃ¤tswÃ¼nsche garantieren kann,\n\nnoch wird es eine PrioritÃ¤t bei der Zuteilung in Verbindung mit der Bereitstellung\n\nÃ¤hnlicher KapazitÃ¤ten geben.\n\nâž¢ Vorentwurf des PaP-Angebots:\n\no Beratung Ã¼ber das KapazitÃ¤tsangebot auf der Grundlage der von den\n\nZugangsberechtigten erhaltenen RÃ¼ckmeldungen und der Erfahrungen der C-\n\n4/22",157,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":4,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","f93782e4680ce90bfeca584b14ce27aa83e4d6baec69240b0fb505c7c9b659da"],["chunk_a9f18f02caa139b481ba9bcb","wiki/sources/inb-2027-anlage-4-10-data.md",9,"Seite 5","OSS und IB/AB auf der Grundlage der Vorjahre und der Ergebnisse der\n\nVerkehrsmarktstudie\n\nâž¢ Konstruktionsphase:\n\no Ãœberwachung der PaP/RC-Konstruktion zur GewÃ¤hrleistung harmonisierter\n\nGrenzÃ¼bergangszeiten, Kalendertagen und Zugparameter\n\nâž¢ Phase der VerÃ¶ffentlichung:\n\no VerÃ¶ffentlichung des PaP-Katalogs zu X-11 im Path Coordination System (PCS)\n\no ÃœberprÃ¼fung des PaP-Katalogs in Zusammenarbeit mit den IMs/ABs,\n\nDurchfÃ¼hrung aller erforderlichen Korrekturen von Fehlern, die von einer der\n\nbeteiligten Parteien erkannt wurden, bis X-10.5\n\no VerÃ¶ffentlichung des Angebots fÃ¼r die Phase der â€žLate Path requestsâ€œ in PCS\n\n(sofern auf dem Korridor â€žLate Pathâ€œ angeboten werden)\n\no VerÃ¶ffentlichung von RC zu X-2 in PCS\n\nâž¢ Zuteilungsphase: Jahresfahrplan (â€œannual timetable processâ€œ))\n\no Sammeln, PrÃ¼fen und ÃœberprÃ¼fen aller Anfragen fÃ¼r PaPs einschlieÃŸlich\n\nFehlerbehebung, wenn mÃ¶glich\n\no Erstellung und Aktualisierung einer Ãœbersicht der Anmeldungen (siehe 2.4.1)\n\no LÃ¶sung von Konflikten durch Konsultation, wo dies mÃ¶glich ist\n\no bei kollidierenden AntrÃ¤gen eine Entscheidung auf der Grundlage der vom\n\nExekutivrat beschlossenen Zuweisungsregeln entlang des Korridors treffen (siehe\n\n3.1 der Rahmenbedingungen fÃ¼r die KapazitÃ¤tszuweisung (Framework for\n\nCapacity Allocation / FCA)\n\no den Zugangsberechtigten, deren AntrÃ¤ge aufgrund eines Konflikts zwischen\n\nmehreren TrassenantrÃ¤gen einen niedrigeren PrioritÃ¤tswert (K-Wert) haben,\n\nalternative PaPs vorschlagen, sofern diese verfÃ¼gbar sind\n\no Ãœbermittlung von Trassenanmeldungen, die nicht bearbeitet werden kÃ¶nnen, an\n\nden betreffenden IB/AB, damit dieser ein maÃŸgeschneidertes Angebot\n\nausarbeiten kann\n\no Vorbuchung von angefragten KapazitÃ¤ten und Information der\n\nZugangsberechtigten Ã¼ber die Ergebnisse zu X-7.5",222,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":5,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","eab22e1196ec70cf241d64ec1bf46d07c678206a61a3940f1104298a1f7c442c"],["chunk_3b8038ed3fb612a3bbb69583","wiki/sources/inb-2027-anlage-4-10-data.md",10,"Seite 5","o Zuweisung von KapazitÃ¤ten (PaPs) in Ãœbereinstimmung mit den einschlÃ¤gigen\n\ninternationalen Fahrplanfristen (siehe 3.12) und den von RailNetEurope (RNE)\n\ndefinierten Prozessen sowie gemÃ¤ÃŸ den in dem FCA beschriebenen\n\nZuweisungsregeln\n\no Ãœberwachung der Konstruktion von Zubringer- und/oder Abbringertrassen (feederund/oder outflow-Trassen), indem die Anfragen an die betroffenen IB/ABs\n\ngesendet werden und deren RÃ¼cklÃ¤ufe/Angebote eingeholt werden. Im Falle von\n\nnicht konsistenten Angeboten (z.B. nicht harmonisierte Grenzzeiten) um Korrektur\n\nbitten\n\no Ãœbermittlung der Antworten/Angebote (Angebotsentwurf und endgÃ¼ltiges Angebot\n\neinschlieÃŸlich feeder/outflow) an die Zugangsberechtigten im Namen der\n\nbetreffenden IB/ABs\n\no Aktualisierung des PaP-Katalogs\n\nâž¢ Zuweisungsphase: â€œLate Path Requestsâ€ (â€žannual timetable processâ€œ), sofern\n\nzutreffend\n\no Sammeln, PrÃ¼fen und ÃœberprÃ¼fen aller AntrÃ¤ge fÃ¼r die Phase â€žLate Path\n\nRequestsâ€œ einschlieÃŸlich Fehlerbehebung, wenn mÃ¶glich\n\no Zuweisung von KapazitÃ¤t fÃ¼r die Phase â€žLate Path Requestsâ€œ\n\no Ãœberwachung der Konstruktion von feeder- und/oder outflow-Trassen, indem die\n\nAnfragen an die betroffenen IB/ABs gesendet werden und deren\n\nRÃ¼cklÃ¤ufe/Angebote eingeholt werden. Im Falle von nicht konsistenten\n\nAngeboten (z.B. nicht harmonisierte Grenzzeiten) um Korrektur bitten\n\n5/22",161,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":5,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","cbde2d38b3a09f52010cb9366232001b1d5012a0205e7e8de96ce032e2a6493f"],["chunk_9506d3348277e3ed0ca3751f","wiki/sources/inb-2027-anlage-4-10-data.md",11,"Seite 6","o Ãœbermittlung der Antworten/Angebote an die Zugangsberechtigten im Namen der\n\nbetreffenden IB/ABs\n\no Aktualisierung des entsprechenden Katalogs\n\nâž¢ Zuweisungsphase: ad-hoc AntrÃ¤ge (Reserve Capacity, RC) (â€œrunning timetable\n\nprocessâ€)\n\no Sammeln, PrÃ¼fen und ÃœberprÃ¼fen aller Anfragen fÃ¼r RC, einschlieÃŸlich\n\nFehlerbehebung, wenn mÃ¶glich\n\no Erstellung und Aktualisierung einer Ãœbersicht Ã¼ber die Anmeldungen\n\no Zuweisung von KapazitÃ¤t fÃ¼r RC\n\no Ãœberwachung der Konstruktion fÃ¼r die feeder- und/oder outflow-Trassen, indem\n\ndie Anfragen an die betroffenen IB/ABs gesendet werden und deren\n\nRÃ¼cklÃ¤ufe/Angebote eingeholt werden. Im Falle von nicht konsistenten Angeboten\n\n(z.B. nicht harmonisierte Grenzzeiten) um Korrektur bitten\n\no Ãœbermittlung der Antworten/Angebote an die Zugangsberechtigten im Namen der\n\nbetreffenden IB/ABs\n\no Aktualisierung des RC-Katalogs\n\n2.4.1 Ãœbersicht der Trassenanmeldungen\n\nDer C-OSS verwaltet und fÃ¼hrt eine Ãœbersicht der Trassenanmeldungen fÃ¼r alle eingehenden\n\nTrassenanmeldungen, die die Daten der Anmeldungen, die Namen der Zugangsberechtigten,\n\nEinzelheiten zu den eingereichten Unterlagen und zu aufgetretenen VorfÃ¤llen enthÃ¤lt. Eine\n\nÃœbersicht der Trassenanmeldungen wird allen betroffenen Zugangsberechtigten frei zugÃ¤nglich\n\ngemacht, ohne die IdentitÃ¤t anderer Zugangsberechtigter preiszugeben, es sei denn, die\n\nbetroffenen Zugangsberechtigten haben einer solchen Offenlegung zugestimmt. Der Inhalt der\n\nÃœbersicht der Trassenanmeldungen wird nur auf Anfrage mitgeteilt.\n\n2.5 Tool\n\nPCS ist das einzige Tool zur VerÃ¶ffentlichung des verbindlichen PaP- und RC-Angebots des\n\nKorridors und zur Vergabe und Verwaltung internationaler Trassenanmeldungen auf dem\n\nKorridor.\n\nAntrÃ¤ge auf PaP/RC kÃ¶nnen nur Ã¼ber PCS an den beteiligten C-OSS gestellt werden. Wird der",223,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":6,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","fc82fc7b5625e4b22134e47ab42c088bba281c469adf8456b2467741c19e427a"],["chunk_7007ce991f4517e746002b0e","wiki/sources/inb-2027-anlage-4-10-data.md",12,"Seite 6","Antrag direkt bei den betroffenen IMs/ABs gestellt, informieren diese den Zugangsberechtigten\n\ndarÃ¼ber, dass er einen korrekten PaP/RC-Antrag gemÃ¤ÃŸ den geltenden Fristen Ã¼ber den C-OSS\n\nin PCS stellen muss. PaP/RC-KapazitÃ¤ten, die nur Ã¼ber nationale Tools beantragt werden,\n\nwerden nicht zugewiesen.\n\nMit anderen Worten: PaP/RC-AntrÃ¤ge kÃ¶nnen nicht Ã¼ber ein anderes Tool als PCS gestellt\n\nwerden.\n\n3 KapazitÃ¤tszuweisung\n\nDie Entscheidung Ã¼ber die Zuteilung von PaPs und RC auf dem Korridor wird vom C-OSS im\n\nNamen der betroffenen IMs/ABs getroffen. Hinsichtlich der feeder- und/oder outflow-Trassen wird\n\ndie Zuweisungsentscheidung von den betroffenen IB/ABs getroffen und dem\n\nZugangsberechtigten vom C-OSS mitgeteilt. Eine konsistente TrassenfÃ¼hrung, die die Zubringerund/oder Abbringerabschnitte und den korridorbezogenen Trassenabschnitt enthÃ¤lt, muss\n\ngewÃ¤hrleistet sein.\n\nAlle notwendigen vertraglichen Beziehungen in Bezug auf den Netzzugang sind bilateral\n\nzwischen dem Zugangsberechtigten und jedem einzelnen IB/AB zu regeln.\n\n3.1 Rahmenbedingungen fÃ¼r die KapazitÃ¤tszuweisung (Framework for Capacity\n\nAllocation / FCA)\n\nUnter Bezugnahme auf Artikel 14.1 der Verordnung einigten sich die ExekutivrÃ¤te der\n\nGÃ¼terverkehrskorridore auf einen gemeinsamen Rahmen fÃ¼r die KapazitÃ¤tszuweisung\n\n6/22",162,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":6,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","0db6126386c49962c62239346e862d40538e223b08d305506c1751d0ff528e35"],["chunk_64ac2e7d99ca4ddcad737291","wiki/sources/inb-2027-anlage-4-10-data.md",13,"Seite 7","(Framework for Capacity Allocation, FCA). Dieses Dokument ist im CIP verfÃ¼gbar unter\n\nhttps://cip-online.rne.eu/. Das FCA bildet die Grundlage fÃ¼r die KapazitÃ¤tszuweisung durch den\n\nC-OSS.\n\n3.2 Zugangsberechtigte\n\nDie Zugangsberechtigten mÃ¼ssen die allgemeinen Bedingungen fÃ¼r den Korridor durch\n\nAnkreuzen des entsprechenden KontrollkÃ¤stchens in PCS akzeptieren, bevor sie ihre AntrÃ¤ge\n\nstellen.\n\nOhne die Zustimmung zu den allgemeinen GeschÃ¤ftsbedingungen kann der Zugangsberechtigte\n\nden Antrag nicht abschicken. Wird ein Antrag von mehreren Zugangsberechtigten gestellt, muss\n\njeder Zugangsberechtigte, der einen PaP-Abschnitt beantragt, die allgemeinen Bedingungen fÃ¼r\n\njeden Korridor akzeptieren, fÃ¼r den er einen PaP-Abschnitt beantragt. Beantragt einer der\n\nZugangsberechtigten nur einen feeder- oder outflow-Abschnitt ist die Annahme der Allgemeinen\n\nGeschÃ¤ftsbedingungen nicht erforderlich.\n\nDie Abnahme erfolgt nur einmal pro Zugangsberechtigtem und pro Korridor und ist fÃ¼r eine\n\nFahrplanperiode gÃ¼ltig.\n\nMit der Annahme erklÃ¤rt der Zugangsberechtigte, dass er:\n\nâž¢ das Corridor Information Document (CID) des Korridors und insbesondere dessen\n\nAbschnitt 4 gelesen, verstanden und akzeptiert hat,\n\nâž¢ alle Bedingungen erfÃ¼llt, die in den geltenden Rechtsvorschriften und von den\n\nIB/ABs festgelegt sind, die an den von ihm beantragten Trassen beteiligt sind,\n\neinschlieÃŸlich aller verwaltungstechnischen und finanziellen Anforderungen,\n\nâž¢ stellt alle fÃ¼r die Trassenanmeldungen erforderlichen Daten zur VerfÃ¼gung,\n\nâž¢ akzeptiert die Bestimmungen der nationalen Schienennetz-Benutzungsbedingungen,\n\ndie fÃ¼r die beantragte(n) Trasse(n) gelten.\n\nIm Falle eines Zugangsberechtigten, der kein EVU ist, benennt dieser das EVU, das fÃ¼r den",216,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":7,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","70f0d66fd0f1bf99edc6e25c532a54b9e117799ac5af061163b6f07d90db2d32"],["chunk_a9cd6614b14b8c6eee4e72fe","wiki/sources/inb-2027-anlage-4-10-data.md",14,"Seite 7","Zugbetrieb zustÃ¤ndig sein wird, und informiert den C-OSS und die IB/ABs so frÃ¼h wie mÃ¶glich,\n\nspÃ¤testens jedoch 30 Tage vor dem Fahrtag. Wird der Termin nicht gemÃ¤ÃŸ dieser Frist\n\nwahrgenommen, gilt der PaP/RC als storniert, und es gelten die nationalen Vorschriften fÃ¼r die\n\nStornierung von Trassen.\n\nHandelt es sich bei dem Zugangsberechtigten um einen Zugangsberechtigten, der kein EVU ist,\n\nund beantragt er eine feeder-/outflow-Trasse, werden die nationalen Vorschriften fÃ¼r die\n\nBenennung des ausfÃ¼hrenden EVU angewandt.\n\n3.3 Anforderungen fÃ¼r KapazitÃ¤tsanfragen\n\nDer Korridor wendet die von RNE definierten internationalen Fahrplanfristen sowohl fÃ¼r die\n\nTrassenanmeldung als auch fÃ¼r die Trassenzuweisung an (zum Terminkalender des Korridors,\n\nsiehe https://rne.eu/capacity-management/capacity-planning-timetabling oder Kapitel 3.12).\n\nAlle AntrÃ¤ge mÃ¼ssen Ã¼ber PCS eingereicht werden, das das einzige Tool fÃ¼r die Beantragung\n\nund Verwaltung von KapazitÃ¤ten auf allen Korridoren ist. Der C-OSS ist nicht berechtigt, PCS-\n\nDossiers im Namen des Zugangsberechtigtes zu erstellen. Auf Wunsch kann der C-OSS die\n\nZugangsberechtigten bei der Erstellung der Dossiers unterstÃ¼tzen, um Unstimmigkeiten zu\n\nvermeiden und die Erwartungen der Zugangsberechtigten zu lenken (maximal 1 Woche vor\n\nAblauf der Antragsfrist). Die IMs/ABs kÃ¶nnen die Zugangsberechtigten unterstÃ¼tzen, indem sie\n\ndie AntrÃ¤ge technisch Ã¼berprÃ¼fen.\n\nEine Anfrage fÃ¼r grenzÃ¼berschreitende SchienengÃ¼terverkehrskapazitÃ¤t Ã¼ber den C-OSS muss\n\ndie folgenden Anforderungen erfÃ¼llen:\n\nâž¢ sie muss mit PCS bei einem C-OSS eingereicht werden, einschlieÃŸlich mindestens\n\neines PaP/RC-Abschnitts. Einzelheiten werden im PCS-Benutzerhandbuch erlÃ¤utert\n\nhttps://docs.rne.eu/pcs/),\n\n7/22",219,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":7,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","68fe2e4a39517ac32566f40320c01dac734584280a70348d8d25e1fdf3e68c1f"],["chunk_5db1145316c2aa971a1124f5","wiki/sources/inb-2027-anlage-4-10-data.md",15,"Seite 8","âž¢ sie muss mindestens eine Grenze in einem Korridor Ã¼berschreiten,\n\nâž¢ sie muss einen Zuglauf vom Ausgangspunkt bis zum Zielort umfassen, einschlieÃŸlich\n\nPaP/RC Abschnitten auf einem oder mehreren Korridoren (sowie ggf. auf feederund/oder outflow-Trassen), an allen seinen Betriebstagen. In bestimmten FÃ¤llen, die\n\nauf technische BeschrÃ¤nkungen von PCS zurÃ¼ckzufÃ¼hren sind, muss ein Antrag\n\nmÃ¶glicherweise in Form von mehr als einem Dossier eingereicht werden. Diese\n\nSonderfÃ¤lle sind die folgenden:\n\no Unterschiedlicher Start- und/oder Zielort je nach Verkehrstag (aber mit\n\nidentischer PaP/RC-KapazitÃ¤t fÃ¼r mindestens einen der IB, fÃ¼r den KapazitÃ¤t\n\nangefragt wurde).\n\no Umschlag von einem Zug auf andere ZÃ¼ge (oder umgekehrt) aufgrund von\n\nBeschrÃ¤nkungen der Infrastruktur.\n\no Die IB/AB fordert den Zugangsberechtigten ausdrÃ¼cklich auf, den Antrag in zwei\n\noder mehr Dossiers aufzuteilen.\n\nDamit der C-OSS solche Dossiers als einen Antrag identifizieren kann und um eine\n\nkorrekte Berechnung des PrioritÃ¤tswerts (K-Wert) zu ermÃ¶glichen, wenn ein Antrag in\n\nmehr als einem Dossier eingereicht werden muss, muss der Zugangsberechtigte die\n\nVerbindung zwischen diesen Dossiers im PCS angeben. AuÃŸerdem muss der\n\nZugangsberechtigte den Grund fÃ¼r die Verwendung von mehr als einem Dossier im\n\nKommentarfeld angeben.\n\nâž¢ die technischen Parameter der Trasse mÃ¼ssen im Rahmen der ursprÃ¼nglich\n\nverÃ¶ffentlichten Parameter der angeforderten PaP-Abschnitte liegen (Ausnahmen\n\nsind mÃ¶glich, wenn der betreffende IB/AB dies erlaubt, z. B. wenn der Zeitplan der\n\nPaP eingehalten werden kann)\n\nâž¢ bei Abschnitten mit flexiblen Zeiten kann der Zugangsberechtigte Zeiten, Stopps und\n\nParameter gemÃ¤ÃŸ seinen individuellen BedÃ¼rfnissen innerhalb des vorgegebenen\n\nBereichs anpassen/einfÃ¼gen.",237,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":8,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","4f3bc5ecf8fc59d43f4767d93d03ea748b69a9baf729d447a656a38ea12e44a0"],["chunk_28dbf9d274df52c021fd7f5f","wiki/sources/inb-2027-anlage-4-10-data.md",16,"Seite 8","Im Falle einiger Korridore kÃ¶nnen weitere Mehrbedarfe fÃ¼r SonderfÃ¤lle gelten. Die Beschreibung\n\nsolcher Anforderungen ist in den CIDs der einzelnen Korridore enthalten.\n\n3.4 Jahresfahrplan-Phase\n\n3.4.1 PaPs\n\nPaPs sind ein gemeinsames Angebot von koordinierten grenzÃ¼berschreitenden Trassen fÃ¼r den\n\nJahresfahrplan, das von den am Korridor beteiligten IMs/ABs erstellt wird. Der C-OSS fungiert\n\nals zentrale Anlaufstelle fÃ¼r die VerÃ¶ffentlichung und Zuweisung von PaPs.\n\nPaPs sind ein Standard-KapazitÃ¤tsprodukt fÃ¼r den internationalen SchienengÃ¼terverkehr. Um\n\ndem FlexibilitÃ¤tsbedÃ¼rfnis der Zugangsberechtigten und der Marktnachfrage auf dem Korridor\n\ngerecht zu werden, werden die PaPs in mehrere Abschnitte aufgeteilt, anstatt als ganze PaPs\n\ngeliefert zu werden. Daher kÃ¶nnte das Angebot auch einige rein nationale PaP-Abschnitte\n\numfassen, die beim C-OSS fÃ¼r grenzÃ¼berschreitende GÃ¼terzÃ¼ge, die mindestens eine Grenze\n\nauf einem Korridor Ã¼berschreiten, im Zusammenhang mit internationalen Trassenanmeldungen\n\nbeantragt werden mÃ¼ssen.\n\nDer C-OSS verÃ¶ffentlicht in Vorbereitung jeder Fahrplanperiode einen Katalog der PaPs. Er wird\n\nin PCS verÃ¶ffentlicht.\n\nDie PaPs werden zu X-11 in PCS verÃ¶ffentlicht. Zwischen X-11 und X-10.5 ist es dem C-OSS\n\ngestattet, in PCS alle erforderlichen Korrekturen von Fehlern in Bezug auf die verÃ¶ffentlichten\n\nPaPs vorzunehmen, die von einer der beteiligten Parteien erkannt wurden. In dieser Phase haben\n\ndie verÃ¶ffentlichten PaPs den Status \"nur lesen\" fÃ¼r Zugangsberechtigte, die dem C-OSS auch\n\nInput zur Korrektur von Fehlern geben kÃ¶nnen.\n\n8/22",208,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":8,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","d281cab2eb0e9a782d96e469d9532fd58d99127701d39b0204cbf34e80a6b725"],["chunk_f3459f746a326d6f6effe8b3","wiki/sources/inb-2027-anlage-4-10-data.md",17,"Seite 9","3.4.2 Schematischer Korridorplan\n\nSchematische Karte(n) der einzelnen Korridore befindet sich im Anhang des jeweiligen CID.\n\n3.4.3 Merkmale von PaPs\n\nEs wird ein PaP-Fahrplan verÃ¶ffentlicht, der eines der folgenden Merkmale enthÃ¤lt:\n\nâž¢ Abschnitte mit festen Zeiten (Daten kÃ¶nnen in der Trassenanmeldung durch einen\n\nZugangsberechtigten nicht geÃ¤ndert werden).\n\no KapazitÃ¤t mit festen Ursprungs-, Zwischen- und Zielzeiten innerhalb eines IB/ABs.\n\no Zwischenpunkte (Intermediate Points) und Betriebspunkte (Operational Points) mit\n\nfesten Zeiten. AntrÃ¤ge auf Ã„nderungen des verÃ¶ffentlichten PaP mÃ¼ssen von den\n\nbetroffenen IMs/ABs geprÃ¼ft werden und kÃ¶nnen nur akzeptiert werden, wenn sie\n\ndurchfÃ¼hrbar sind und sich dadurch die Berechnung der Zuweisungsregel bei\n\nkollidierenden AntrÃ¤gen bei X-8 nicht Ã¤ndert.\n\nâž¢ Abschnitte mit flexiblen Zeiten (die Daten kÃ¶nnen im Trassenantrag vom\n\nZugangsberechtigte gemÃ¤ÃŸ dem individuellen Bedarf geÃ¤ndert werden, ohne jedoch die\n\nvorgegebene Bandbreite der Standardfahrzeiten, Haltezeiten und Zugparameter zu\n\nÃ¼berschreiten. Gegebenenfalls mÃ¼ssen die maximale Anzahl der Halte und die\n\nGesamthaltezeit pro Abschnitt eingehalten werden).\n\no Den Zugangsberechtigten steht es frei, innerhalb der im PaP-Katalog genannten\n\nParameter ihre eigenen Anforderungen in ihren PaP-Antrag aufzunehmen.\n\no Gegebenenfalls ist die Angabe von Standardlaufzeiten fÃ¼r jeden Streckenabschnitt\n\ndes Korridors zu beachten.\n\no Optional: Zwischenpunkte (Intermediate Points) ohne feste Zeiten. Andere Punkte auf\n\ndem Korridor kÃ¶nnen angefordert werden.\n\no Optional: Betriebspunkte (Operational Points) ohne feste Zeiten.\n\nAntrÃ¤ge auf Ã„nderungen auÃŸerhalb der oben genannten FlexibilitÃ¤t mÃ¼ssen von den betroffenen",217,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":9,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","e7ac5d2db3270bc2c3f8522299b6934d8fb685c2990e4230485c0fd9ce447db2"],["chunk_62da13a2918cc9ef6727fc0d","wiki/sources/inb-2027-anlage-4-10-data.md",18,"Seite 9","IB/ABs geprÃ¼ft werden, wenn sie die AntrÃ¤ge akzeptieren. Die Ã„nderungen kÃ¶nnen nur akzeptiert\n\nwerden, wenn sie durchfÃ¼hrbar sind.\n\nDer C-OSS fÃ¶rdert die PaPs, indem er sie bestehenden und potenziellen Zugangsberechtigten\n\nvorstellt.\n\nFÃ¼r die Beschreibung weiterer Besonderheiten wird auf die CIDs der einzelnen Korridore\n\nverwiesen.\n\nBei einigen Korridoren kann der KapazitÃ¤tsbandbreitenansatz angewendet werden. FÃ¼r die\n\nBeschreibung der Merkmale spezifischer KapazitÃ¤tsbandbreitenansÃ¤tze wird auf die CIDs der\n\neinzelnen Korridore verwiesen.\n\n3.4.4 â€žMultiple corridor pathsâ€œ (Korridortrassen, die auf mehreren Korridoren liegen)\n\nEs ist mÃ¶glich, dass sich die KapazitÃ¤tsanfragen auf mehr als einen Korridor beziehen. Ein durch\n\nverschiedene Korridore harmonisiertes PaP-Angebot kann verÃ¶ffentlicht und als solches\n\ngekennzeichnet werden. Der Zugangsberechtigte kann innerhalb einer Anfrage PaP-Abschnitte\n\nauf verschiedenen Korridoren beantragen. Jeder C-OSS bleibt fÃ¼r die Zuweisung seiner eigenen\n\nPaP-Abschnitte verantwortlich, aber der Zugangsberechtigte kann seine Fragen nur an einen der\n\nbeteiligten C-OSS richten, der sich bei Bedarf mit den anderen betroffenen C-OSS abstimmt.\n\nâ€žMultiple corridor pathsâ€œ auf dem Korridor sind auf einer Karte in Anlage 4C des CID fÃ¼r jeden\n\nKorridor darzustellen.\n\n3.4.5 PaPs auf Ã¼berlappenden Abschnitten\n\nDie Anordnung der Korridorstrecken fÃ¼hrt zu Situationen, in denen sich einige Korridorstrecken\n\nmit anderen Ã¼berschneiden. Ziel der Korridore ist es in diesem Fall, unter BerÃ¼cksichtigung der\n\nunterschiedlichen VerkehrsstrÃ¶me das bestmÃ¶gliche Angebot zu erstellen und die mÃ¶glichen\n\nLÃ¶sungen zur Verbindung der betreffenden Ãœberschneidungsabschnitte mit den Ã¼brigen\n\nKorridoren aufzuzeigen.\n\n9/22",219,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":9,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","8c6d83b46353c7aa233ae274ff06cff82f9d4fceaf4aa892e60bceb972b1e4b6"],["chunk_d1f3dc3533c0de4f53b94945","wiki/sources/inb-2027-anlage-4-10-data.md",19,"Seite 10","Bei sich Ã¼berschneidenden Abschnitten kÃ¶nnen die Korridore ein gemeinsames Angebot\n\nentwickeln, das fÃ¼r alle betroffenen Korridore sichtbar ist. Die beteiligten Korridore legen fest,\n\nwelcher C-OSS fÃ¼r die endgÃ¼ltige Entscheidung Ã¼ber die Zuweisung der verÃ¶ffentlichten\n\nKapazitÃ¤t zustÃ¤ndig ist. Im Konfliktfall entscheidet der zustÃ¤ndige C-OSS gemeinsam mit den\n\nanderen C-OSS, welcher Antrag Vorrang haben soll. In jedem Fall wird der Zugangsberechtigte\n\nvon dem zustÃ¤ndigen C-OSS konsultiert.\n\nDie Beschreibung der gemeinsamen Angebote auf den sich Ã¼berschneidenden Abschnitten ist\n\nauf einer Karte in Anlage 4C des CID fÃ¼r jeden Korridor darzustellen. Angaben zum\n\nverantwortlichen C-OSS sind in den CIDs der einzelnen Korridore enthalten.\n\n3.4.6 Feeder, outflow und â€žtailor-madeâ€œ (maÃŸgeschneiderte)-Trassen\n\nFalls die verfÃ¼gbaren PaP nicht die gesamte beantragte Trasse abdecken, kann der\n\nZugangsberechtigte eine feeder- und/oder outflow-Trasse zu seinem PaP-Abschnitt in seiner\n\ninternationalen Anmeldung, die via PCS in einer Anfrage an den C-OSS gerichtet ist, angeben.\n\nEine feeder-/outflow-Trasse ist ein beliebiger Trassenabschnitt vor dem Erreichen eines\n\nZwischenpunktes (intermediate point) auf einem Korridor (feeder-Trasse) oder ein\n\nTrassenabschnitt nach dem Verlassen eines Korridors an einem Zwischenpunkt (outflow-Trasse).\n\nFeeder-/Outflow-Trassen werden auf Antrag in den betreffenden PCS-Dossiers nach den\n\nnationalen Trassenzuweisungsregeln gebaut. Das Angebot wird dem Zugangsberechtigten vom\n\nC-OSS innerhalb des gleichen Zeitrahmens, der fÃ¼r die Mitteilung der angeforderten PaPs zur\n\nVerfÃ¼gung steht, mitgeteilt.\n\nDie Beantragung einer maÃŸgeschneiderten Trasse zwischen zwei PaP-Abschnitten ist mÃ¶glich,",215,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":10,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","ef134ccd294d3a16087f9dc1b4f7e5feeba174dd1c8889a6736570acb4a17369"],["chunk_062521fa6586fc95ff2e13fa","wiki/sources/inb-2027-anlage-4-10-data.md",20,"Seite 10","aber aufgrund der Schwierigkeit fÃ¼r IMs/ABs, zwei PaP-Abschnitte zu verbinden, ist ein\n\ngeeignetes Angebot weniger wahrscheinlich (fÃ¼r weitere ErlÃ¤uterungen siehe 3.4.14).\n\nDiagramm mit mÃ¶glichen Szenarien fÃ¼r feeder-/outflow-Trassen (paths) in Verbindung mit einer\n\nAnforderung fÃ¼r einen oder mehrere PaP-Abschnitt(e) (sections):\n\n3.4.7 Bearbeitung von Anfragen\n\nDer C-OSS verÃ¶ffentlicht den PaP-Katalog zu X-11 in PCS, prÃ¼ft ihn in Zusammenarbeit mit den\n\nIMs/ABs und fÃ¼hrt alle erforderlichen Korrekturen der von einer der beteiligten Parteien erkannten\n\nFehler bis X-10.5 durch. Zugangsberechtigte kÃ¶nnen ihre AntrÃ¤ge bis X-8 einreichen. Der C-OSS\n\nbietet Zugangsberechtigten eine zentrale Anlaufstelle, bei der sie in einem einzigen Vorgang\n\nAnfragen zur KorridorkapazitÃ¤t fÃ¼r grenzÃ¼berschreitende GÃ¼terzÃ¼ge, die mindestens eine Grenze\n\n10/22",107,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":10,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","2bd4b9fd998d591582182cb36179b70b54c790c9311b746636d2b4688ff07044"],["chunk_ae0f4e62c8cbaca5099b429f","wiki/sources/inb-2027-anlage-4-10-data.md",21,"Seite 11","auf einem Korridor Ã¼berqueren, stellen und Antworten erhalten kÃ¶nnen. Auf Wunsch kann der C-\n\nOSS die Zugangsberechtigten bei der Erstellung der Dossiers unterstÃ¼tzen, um Unstimmigkeiten\n\nzu vermeiden und die Erwartungen der Zugangsberechtigten zu lenken. Die IMs/ABs kÃ¶nnen die\n\nZugangsberechtigten unterstÃ¼tzen, indem sie die AntrÃ¤ge technisch Ã¼berprÃ¼fen.\n\n3.4.8 FÃ¼hrendes Tool fÃ¼r die Bearbeitung von KapazitÃ¤tsanfragen\n\nZugangsberechtigte, die AntrÃ¤ge an den C-OSS richten, mÃ¼ssen PCS verwenden. Im Rahmen\n\ndes Konstruktionsprozesses fÃ¼r feeder- und/oder ouflow-Trassen und maÃŸgeschneiderten\n\n(tailormade) Trassen kann das nationale Tool dem Zugangsberechtigte zusÃ¤tzliche Informationen\n\nanzeigen.\n\nDie folgende Matrix zeigt fÃ¼r jeden Prozessschritt, welches Tool als fÃ¼hrend angesehen wird:\n\ne s a h P g n u d le m n A X s i ) b 8 ( - e m h a n k c Ã¼ R X )8 ( - g n u h c u b ro V )5 X .7 ( - s e n ie fru w tn E s to b e g n A X )5 ( - e m h a n g n u lle tS X s ib X ) 5 4 ( - - e g n A s e la n iF - X ( ) 5 to . b 3 - s ib ( e m h a n n A 5 2 X 3 - ) .\n\nh\n\nc ru d g n u re d n Ã„ X h c a n ( B ) Z 4 -\n\nh\n\nc ru d g n u re d n Ã„ h c a n ( U I ) E X 4 - g n u re in ro tS X h c a ) n 4 ( -\n\nFÃ¼hrendes\n\nPCS PCS PCS PCS PCS PCS PCS pathOS pathOS pathOS\n\nTool\n\nZusÃ¤tzliches E-Mail\n\nTool (fÃ¼r\n\nInformationen\n\nzur\n\nVoranmeldung)\n\n3.4.9 ÃœberprÃ¼fung der AntrÃ¤ge\n\nDer C-OSS geht davon aus, dass der Zugangsberechtigte die verÃ¶ffentlichten PaP-Merkmale\n\nakzeptiert hat, indem er den ausgewÃ¤hlten PaP anfragt. FÃ¼r alle eingehenden KapazitÃ¤tsanfragen\n\nfÃ¼hrt er jedoch die folgenden PlausibilitÃ¤tsprÃ¼fungen durch:\n\nâž¢ Antrag auf einen GÃ¼terzug, der die PaP nutzt und mindestens eine Grenze auf\n\neinem Korridor Ã¼berschreitet\n\nâž¢ Antrag ohne grÃ¶ÃŸere Ã„nderung der Parameter",359,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":11,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","3a64b70e7ccf13d7cf19104dfde20ca14ec38f063b6c7d6255851a7eba880248"],["chunk_e71ee8ac638b0b31c019ea93","wiki/sources/inb-2027-anlage-4-10-data.md",22,"Seite 11","Liegen PlausibilitÃ¤tsmÃ¤ngel vor, kann der C-OSS mit dem Zugangsberechtigten prÃ¼fen, ob diese\n\nbehoben werden kÃ¶nnen:\n\nâž¢ Wenn das Problem gelÃ¶st werden kann, wird der Antrag vom C-OSS (nach\n\nZustimmung des betroffenen Zugangsberechtigten) korrigiert und wie alle anderen\n\nAntrÃ¤ge bearbeitet. Der Zugangsberechtigte muss die Korrekturen innerhalb von 5\n\nKalendertagen annehmen oder ablehnen. Falls der Zugangsberechtigte nicht\n\nantwortet oder die Korrekturen ablehnt, leitet der C-OSS den ursprÃ¼nglichen Antrag\n\nan den betreffenden IB/AB weiter.\n\nâž¢ Wenn das Problem nicht gelÃ¶st werden kann, wird der Antrag abgelehnt.\n\nAlle Anfragen, die nicht dem verÃ¶ffentlichten Angebot entsprechen, werden vom C-OSS\n\nunverzÃ¼glich zur weiteren Bearbeitung an den betreffenden IB/AB weitergeleitet. In diesen FÃ¤llen\n\nwerden die Antworten von dem betreffenden IB/AB gegeben. Die IB/ABs akzeptieren sie als\n\nrechtzeitig gestellt (d. h. bis X-8).\n\nIm Falle einiger Korridore kÃ¶nnen zusÃ¤tzliche PrÃ¼fungen durchgefÃ¼hrt werden. Eine\n\nBeschreibung dieser zusÃ¤tzlichen PrÃ¼fungen finden sich in den CIDs der einzelnen Korridore.\n\nBei fehlenden oder inkonsistenten Daten wendet sich der C-OSS direkt an den federfÃ¼hrenden\n\nZugangsberechtigten und fordert ihn auf, die entsprechenden Daten innerhalb von 5\n\nKalendertagen zu aktualisieren/zu Ã¤ndern.\n\n11/22",176,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":11,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","a8704c527f67923a6d51b9226e9639b01fca05035e5cc389d550d9b085380dfa"],["chunk_638111a7e8a16b3d01e1787b","wiki/sources/inb-2027-anlage-4-10-data.md",23,"Seite 12","Generell gilt: EnthÃ¤lt eine Anfrage PaPs auf mehreren Korridoren, prÃ¼fen die betroffenen C-OSS\n\ndie KapazitÃ¤tsanfrage in Zusammenarbeit mit den anderen beteiligten C-OSS, um deren\n\nKooperation bei der Bearbeitung von Anfragen mit mehreren Korridoren sicherzustellen. Auf\n\ndiese Weise wird die kumulierte LÃ¤nge der auf jedem Korridor angefragten PaPs verwendet, um\n\nden PrioritÃ¤tswert (K-Wert) mÃ¶glicher kollidierender Anfragen zu berechnen (siehe weitere\n\nEinzelheiten in 3.4.11). Die verschiedenen Korridore kÃ¶nnen somit als Teil eines einzigen\n\nkombinierten Netzes betrachtet werden.\n\n3.4.10 Vorbuchungsphase\n\nBei kollidierenden Anfragen fÃ¼r PaPs, die bis X-8 gestellt werden, wird eine Zuweisungsregel\n\nangewendet. Die Zuweisungsregeln sind im FCA (siehe 3.1) und in 3.4.11 angegeben.\n\nIm Auftrag der betroffenen IB/ABs und gemÃ¤ÃŸ dem Ergebnis der Anwendung der\n\nZuweisungsregeln - wie in 3.4.11 beschrieben - bucht der C-OSS die PaPs vor.\n\nDer C-OSS leitet auch die beantragte feeder-/outflow-Trasse und/oder die Anpassung an die\n\nbetroffenen IB/AB weiter, um ein Fahrplanangebot zu erstellen, das zu dem bereits reservierten\n\n(vorgebuchten) PaP passt, genauso wie es bei AntrÃ¤gen mit einem niedrigeren PrioritÃ¤tswert der\n\nFalls sein kann (Zuweisungsregelprozess unten). Letztere werden in der folgenden Reihenfolge\n\nbearbeitet werden:\n\nâž¢ die Beratung kann angewandt werden\n\nâž¢ Alternativen kÃ¶nnen angeboten werden (falls verfÃ¼gbar)\n\nâž¢ Wenn keiner der oben genannten Schritte angewandt wurde oder erfolgreich war, wird\n\nder angeforderte Zeitplan an die betroffenen IB/AB weitergeleitet, um ein\n\nmaÃŸgeschneidertes (tailormade) Angebot zu erstellen, das der ursprÃ¼nglichen Anfrage so\n\nnahe wie mÃ¶glich kommt.\n\n3.4.11 Zuweisungsregeln bei der KapazitÃ¤tsvergabe",233,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":12,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","55bd62a898c1d6eb45c5f7dd7b31b0b917dee823cf8dcfab814216bc599aa293"]]');
INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_2a5f77ce66e2e1669902184a","wiki/sources/inb-2027-anlage-4-10-data.md",24,"Seite 12","Konflikte werden mit den folgenden Schritten gelÃ¶st, die im Einklang mit dem FCA stehen:\n\nâž¢ Eine LÃ¶sung durch Konsultation kann zwischen Zugangsberechtigten und dem C-OSS\n\ngefÃ¶rdert und durchgefÃ¼hrt werden, wenn die folgenden Kriterien erfÃ¼llt sind:\n\no Der Konflikt erstreckt sich nur auf einen einzigen Korridor.\n\no Geeignete alternative PaPs sind verfÃ¼gbar.\n\nâž¢ Anwendung der Zuweisungsregeln, wie in Anhang 1 des FCA (siehe 3.1) und in 3.4.12\n\nbeschrieben.\n\nDie Tabelle der Entfernungen in Anlage 4.E zum CID jedes Korridors zeigt die bei der\n\nPrioritÃ¤tsberechnung berÃ¼cksichtigten Entfernungen.\n\nâž¢ Auswahl nach dem Zufallsprinzip (siehe 3.4.13).\n\nFalls mehr als ein PaP fÃ¼r den verÃ¶ffentlichten Referenz-PaP verfÃ¼gbar ist, bucht der C-OSS die\n\nPaPs mit der hÃ¶chsten PrioritÃ¤t vor, bis der verÃ¶ffentlichte Schwellenwert erreicht ist. Wenn dieser\n\nSchwellenwert erreicht ist, wendet der C-OSS das Verfahren zur Behandlung von Anfragen mit\n\nniedrigerer PrioritÃ¤t an, wie oben aufgefÃ¼hrt.\n\nIm Falle einiger Korridore kann die LÃ¶sung durch Konsultation angewendet werden. FÃ¼r die\n\nBeschreibung einer solchen LÃ¶sung durch Konsultation, siehe in den CIDs der einzelnen\n\nKorridore.\n\n3.4.12 Verfahren zur Berechnung der Zuweisung\n\nDie Zuweisung wird nach folgender Formel berechnet:\n\nK = (LPAP + LF/O) x YRD\n\n12/22",187,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":12,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","006366b3e10fca6d667abab99f0abcf66a5c1b5dea9e4886008cdaa6324311b7"],["chunk_26477084342a36fba692daa2","wiki/sources/inb-2027-anlage-4-10-data.md",25,"Seite 13","LPAP = Beantragte GesamtlÃ¤nge aller Abschnitte von vorab festgelegten Trassen (PaPs) in allen\n\nbeteiligten SchienengÃ¼terverkehrskorridoren einer Anfrage. Die Definition einer Anfrage findet\n\nsich in 3.3.\n\nLF/O = Beantragte GesamtlÃ¤nge der Zubringer/Abbringertrassen (feeder/outflow-Trassen), die in\n\neinem Antrag enthalten sind.\n\nYRD = Anzahl der beantragten Betriebstage fÃ¼r den Fahrplanzeitraum. Ein Betriebstag wird nur\n\ndann fÃ¼r die Zuweisungsberechnung berÃ¼cksichtigt, wenn er sich auf ein Datum mit einem\n\nverÃ¶ffentlichten PaP-Angebot fÃ¼r den betreffenden Abschnitt bezieht.\n\nK = PrioritÃ¤tsgrad\n\nAlle LÃ¤ngen sind in Kilometern angegeben.\n\nDie Formel wird nach folgender Methode angewandt:\n\nâˆ’ In einem ersten Schritt wird der PrioritÃ¤tswert (K) berechnet, indem nur die beantragte\n\nGesamtlÃ¤nge der vorab vereinbarten Trasse (LPAP) multipliziert mit der Anzahl der\n\nbeantragten Betriebstage verwendet wird (YRD);\n\nâˆ’ KÃ¶nnen die AntrÃ¤ge nicht auf diese Weise getrennt werden, wird der PrioritÃ¤tswert (K)\n\nunter Verwendung der GesamtlÃ¤nge der vollstÃ¤ndigen Trassen berechnet (LPAP + LF/O)\n\nmultipliziert mit der Anzahl der beantragten Betriebstage (YRD), um die AntrÃ¤ge zu trennen;\n\nâˆ’ KÃ¶nnen die AntrÃ¤ge so nicht getrennt werden, erfolgt die Auswahl nach dem\n\nZufallsprinzip, um die AntrÃ¤ge zu trennen. Diese Auswahl nach dem Zufallsprinzip wird in\n\n3.4.13 beschrieben.\n\n3.4.13 Auswahl nach dem Zufallsprinzip\n\nWenn die Anfragen nicht nach den oben genannten Zuweisungsregeln getrennt werden kÃ¶nnen,\n\nwird eine Auswahl nach dem Zufallsprinzip zur Trennung der AntrÃ¤ge verwendet.\n\nâž¢ Die jeweiligen Zugangsberechtigten werden vor X-7.5 Ã¼ber den unentschiedenen\n\nKonflikt informiert und zu einer Auslosung eingeladen.\n\nâž¢ Die eigentliche Auslosung wird vom C-OSS vorbereitet und ausgefÃ¼hrt, wobei",239,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":13,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","660744751d56df22abe5151fa01525928098e4f7e9b25b261c789203a34570c2"],["chunk_e968dc5f25b243f68717f7e0","wiki/sources/inb-2027-anlage-4-10-data.md",26,"Seite 13","vollstÃ¤ndige Transparenz gewÃ¤hrleistet ist.\n\nâž¢ Das Ergebnis der Auslosung wird allen Beteiligten, ob anwesend oder nicht, vor X-\n\n7.5. per PCS und E-Mail mitgeteilt.\n\n3.4.14 SonderfÃ¤lle von AntrÃ¤gen und deren Behandlung\n\nAus der Zuteilung in den vergangenen Fahrplanperioden ist folgende besondere Nutzung von\n\nPaPs bekannt: Aufteilung des kontinuierlichen Angebots in Anteile, die durch die PaP-ID\n\nidentifiziert werden (PaPs / Nicht-PaPs). Dies bezieht sich auf den Fall, dass Zugangsberechtigte\n\nKorridorkapazitÃ¤t (fÃ¼r einen oder mehrere Korridore) in der folgenden Reihenfolge nachfragen:\n\n1) PaP-Abschnitt (PaP-Section)\n\n2) MaÃŸgeschneiderter Abschnitt (Tailormade Section)\n\n3) PaP-Abschnitt\n\n13/22",90,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":13,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","ffed9859701e190cb30725777b2fff585e61612ecc253fb4aa70e44481e345d9"],["chunk_a63bdc414dbb6f39541b6e56","wiki/sources/inb-2027-anlage-4-10-data.md",27,"Seite 14","Diese AntrÃ¤ge werden je nach dem im Antrag angegebenen Ausgangspunkt der Konstruktion wie\n\nfolgt berÃ¼cksichtigt:\n\nâž¢ Konstruktionsstartpunkt am Anfang: Das C-OSS bucht die PaP-Abschnitte vom\n\nUrsprung bis zum Ende des ersten durchgehenden PaP-Abschnitts vor. Abschnitte\n\nnach der Unterbrechung von PaP-Abschnitten werden nicht vorgebucht; sie werden\n\nals maÃŸgeschneidert behandelt.\n\nâž¢ Konstruktionsstartpunkt am Ende: Das C-OSS bucht die PaP-Abschnitte vom Ziel der\n\nAnfrage bis zum Beginn des letzten durchgehenden PaP-Abschnitts vor. Abschnitte\n\nnach der Unterbrechung von PaP-Abschnitten werden nicht vorgebucht; sie werden\n\nals maÃŸgeschneidert behandelt.\n\nâž¢ Konstruktionsstartpunkt in der Mitte: Das C-OSS bucht den lÃ¤ngsten der\n\nangeforderten PaP-Abschnitte entweder vor oder nach der Unterbrechung vor. Andere\n\nAbschnitte werden nicht vorgebucht; sie werden als maÃŸgeschneidert behandelt.\n\nIn jedem der oben genannten FÃ¤lle kann jedoch die angefragte PaP-KapazitÃ¤t, die\n\nmaÃŸgeschneidert wird, zu einem spÃ¤teren Zeitpunkt zugewiesen werden, wenn die IB/ABs den\n\nmaÃŸgeschneiderten Anteil wie gewÃ¼nscht liefern kÃ¶nnen. Im Falle einer Zuweisung behÃ¤lt der\n\nPaP-Anteil, der maÃŸgeschneidert werden kann, seinen vollen Schutz. Diese Art von Anfrage hat\n\nkeinen Einfluss auf die Anwendung der Zuweisungsregel.\n\n3.4.15 Ergebnis der Vorbuchung\n\nDer C-OSS stellt den Zugangsberechtigten vorlÃ¤ufige Informationen Ã¼ber den Stand ihres\n\nAntrags bis spÃ¤testens zu X-7.5. zur VerfÃ¼gung.\n\nWurde eine Konsultation durchgefÃ¼hrt, werden die betroffenen Zugangsberechtigten Ã¼ber das\n\nErgebnis informiert.\n\nWurde keine Konsultation durchgefÃ¼hrt, werden die Zugangsberechtigten mit einem hÃ¶heren\n\nPrioritÃ¤tswert (K-Wert) per Zwischenmitteilung Ã¼ber Vorbuchungsentscheidungen zu ihren\n\nGunsten informiert.",223,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":14,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","d2f39fad4089cf3daded915e66b9595d7cca82bbb4db6ea7e447d73628fb3e39"],["chunk_fb5330cd823af960b7095c1a","wiki/sources/inb-2027-anlage-4-10-data.md",28,"Seite 14","Im Falle von kollidierenden AntrÃ¤gen, mit einem niedrigeren PrioritÃ¤tswert bietet der C-OSS eine\n\nalternative PaP an, sofern verfÃ¼gbar. Der betreffende Zugangsberechtigte muss die angebotene\n\nAlternative innerhalb von 5 Kalendertagen annehmen oder ablehnen. Falls der\n\nZugangsberechtigte nicht antwortet, die Alternative ablehnt oder keine Alternative verfÃ¼gbar ist,\n\n14/22",46,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":14,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","de76058678631081cf07d3b8bd0ee55944eb7cd15dc9df2500c1bcbc5edab058"],["chunk_d2761ba35a8bb84d3e991422","wiki/sources/inb-2027-anlage-4-10-data.md",29,"Seite 15","leitet der C-OSS den ursprÃ¼nglichen Antrag an den betreffenden IB/AB weiter. Der C-OSS\n\ninformiert den Zugangsberechtigten mit einem niedrigeren PrioritÃ¤tswert (K-Wert) bis X-7.5\n\ndarÃ¼ber, dass sein Trassenantrag zur weiteren Bearbeitung im Rahmen des regulÃ¤ren Prozesses\n\nder Netzfahrplanerstellung an den betreffenden IB/AB weitergeleitet wurde und dass der C-OSS\n\nden Entwurf des Trassenangebots im Auftrag des betreffenden IB/AB zu X-5 Ã¼ber PCS\n\nbereitstellen wird. Diese AntrÃ¤ge werden vom betreffenden IB/AB als termingerechte AntrÃ¤ge fÃ¼r\n\nden Jahresfahrplan behandelt und gehen somit in den regulÃ¤ren nationalen Konstruktionsprozess\n\ndes Jahresfahrplans ein.\n\n3.4.16 Behandlung von nicht angefragten PaPs\n\nEs gibt zwei MÃ¶glichkeiten, nicht angefragte PaPs zu X-7.5 zu behandeln, basierend auf der\n\njeweiligen Entscheidung des MB.\n\nA) Nach der Vorbuchung werden alle nicht angeforderten PaPs an den IB/AB Ã¼bergeben.\n\nB) Der Verwaltungsrat trifft eine Entscheidung Ã¼ber die KapazitÃ¤t, die nach X-7.5 neu\n\nverÃ¶ffentlicht wird. Diese Entscheidung hÃ¤ngt von der \"Buchungssituation\" zu diesem\n\nZeitpunkt ab. Genauer gesagt, mÃ¼ssen mindestens die folgenden drei Kriterien (in der\n\nfolgenden Reihenfolge erfÃ¼llt sein):\n\n1. Es muss genÃ¼gend KapazitÃ¤t fÃ¼r â€žLate Path Requestsâ€œ (falls angeboten) und RC\n\nvorhanden sein.\n\n2. BerÃ¼cksichtigung der Nachfrage nach grenzÃ¼berschreitenden Trassen fÃ¼r\n\nGÃ¼terzÃ¼ge, die nicht Ã¼ber PCS gebucht wurden.\n\n3. BerÃ¼cksichtigung der Notwendigkeit einer Ã„nderung des KapazitÃ¤tsangebots\n\naufgrund mÃ¶glicher Ã„nderungen in der Planung von TCRs (vorÃ¼bergehenden\n\nKapazitÃ¤tsbeschrÃ¤nkungen).\n\nInformationen Ã¼ber die Art und Weise, wie die nicht angeforderten PaPs gehandhabt werden,\n\nsind im CID jedes Korridors enthalten.",229,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":15,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","4e7d4fa4822a995edce63b7765f596b2876687d32e31036f723e9c0deabb4414"],["chunk_1307ca248773e32dd7d80f71","wiki/sources/inb-2027-anlage-4-10-data.md",30,"Seite 15","Auf den GÃ¼terverkehrskorridoren mit DB InfraGO AG-Beteiligung wird Option A angewandt.\n\n3.4.17 Angebotsentwurf\n\nNach Erhalt der Vorbuchungsentscheidung durch den C-OSS arbeiten die betroffenen IMs/ABs\n\ndie flexiblen Teile der AntrÃ¤ge aus:\n\nâž¢ Feeder, outflow oder Zwischenabschnitte (intermediate sections)\n\nâž¢ Vorgebuchte Abschnitte, fÃ¼r die der verÃ¶ffentlichte Fahrplan aufgrund Ã¤uÃŸerer\n\nEinflÃ¼sse, z.B. vorÃ¼bergehende KapazitÃ¤tsbeschrÃ¤nkungen, nicht mehr verfÃ¼gbar ist\n\nâž¢ Bei vom Zugangsberechtigte beantragten Ã„nderungen des verÃ¶ffentlichten Zeitplans\n\nâž¢ Im Falle eines Alternativangebots, das vom Zugangsberechtigten abgelehnt wurde\n\noder nicht verfÃ¼gbar ist\n\nFalls die IMs/ABs den Angebotsentwurf nicht erstellen kÃ¶nnen, weil bestimmte WÃ¼nsche des\n\nZugangsberechtigten nicht realisierbar sind, muss der C-OSS den Antrag ablehnen.\n\nDie C-OSSe werden Ã¼ber den Fortschritt informiert, insbesondere Ã¼ber die Teile der AntrÃ¤ge, die\n\nnicht erfÃ¼llt werden kÃ¶nnen, sowie Ã¼ber Konflikte und Probleme bei der Harmonisierung der\n\nTrassenangebote.\n\nZum Stichtag des RNE-Fahrplanentwurf (X-5) Ã¼bermittelt der C-OSS dem Zugangsberechtigten\n\nim Namen des betreffenden IB/AB Ã¼ber PCS den Entwurf des Fahrplanangebots fÃ¼r jeden\n\nbearbeiteten Antrag in Bezug auf vorgebuchte PaPs, einschlieÃŸlich feeder- und/oder outflow,\n\nmaÃŸgeschneiderten Abschnitten (tailor-mades sections) und maÃŸgeschneiderten Angeboten im\n\nFalle von kollidierenden Anfragen.\n\n3.4.18 Stellungnahmen\n\nDie Zugangsberechtigten kÃ¶nnen einen Monat ab dem in Ziffer 3.12 genannten Datum\n\nStellungnahmen zum Fahrplanentwurf in PCS abgeben, die vom C-OSS Ã¼berwacht werden. Der\n\n15/22",201,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":15,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","e739c9ce2177ae57e771676ef3247b9f36ded88cbebdfaf9837ea46b97120418"],["chunk_476e7a7d07c20dfb63c1843a","wiki/sources/inb-2027-anlage-4-10-data.md",31,"Seite 16","C-OSS kann die Zugangsberechtigten bei ihren Stellungnahmen unterstÃ¼tzen. Dieses Verfahren\n\nbetrifft nur Stellungnahmen, die sich auf die ursprÃ¼ngliche Trassenanmeldung beziehen -\n\nwÃ¤hrend Ã„nderungen an den ursprÃ¼nglichen Trassenanmeldungen wie in 3.7.1 beschrieben\n\nbehandelt werden (ohne weitere Beteiligung des C-OSS).\n\n3.4.19 Nacharbeitung\n\nBasierend auf den oben erwÃ¤hnten Stellungnahmen haben die IMs/ABs die MÃ¶glichkeit,\n\nAngebote zwischen X-4 und X-3.5 zu Ã¼berarbeiten. Das aktualisierte Angebot wird dem C-OSS\n\nzur VerfÃ¼gung gestellt, der - nach einer KonsistenzprÃ¼fung - das endgÃ¼ltige Angebot an den\n\nZugangsberechtigten in PCS weiterleitet.\n\n3.4.20 EndgÃ¼ltiges Angebot\n\nZum endgÃ¼ltigen Angebotstermin (X-3.5) Ã¼bermittelt der C-OSS das endgÃ¼ltige Fahrplanangebot\n\nan die Zugangsberechtigten Ã¼ber PCS im Namen des betreffenden IB/AB fÃ¼r jede gÃ¼ltige PaP\n\nAnfrage einschlieÃŸlich feeder und/oder outflow, tailor-made (maÃŸgeschneiderte) Abschnitte und\n\ntailor-made Angeboten fÃ¼r den Fall kollidierender AntrÃ¤ge. Wenn aus betrieblichen GrÃ¼nden\n\nweiterhin eine VerÃ¶ffentlichung Ã¼ber nationale Tools erforderlich ist (z. B. zur Erstellung von\n\nDokumenten fÃ¼r TriebfahrzeugfÃ¼hrer), mÃ¼ssen die IB/AB sicherstellen, dass es keine\n\nDiskrepanzen zwischen PCS und dem nationalen Tool gibt.\n\nDie beteiligten Zugangsberechtigten mÃ¼ssen das endgÃ¼ltige Angebot innerhalb von 7\n\nKalendertagen in PCS annehmen oder ablehnen.\n\nâž¢ Akzeptanz > fÃ¼hrt zur Zuweisung\n\nâž¢ Ablehnung > fÃ¼hrt zur RÃ¼cknahme und SchlieÃŸung des Antrags\n\nâž¢ Keine Antwort > Der C-OSS wird aktiv versuchen, eine Antwort zu erhalten. Falls keine\n\nAntwort von den Zugangsberechtigten vorliegt, wird der C-OSS den Vorgang beenden\n\n(keine Zuweisung).\n\nWenn nicht alle Zugangsberechtigten mit dem endgÃ¼ltigen Angebot einverstanden sind, wird die",232,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":16,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","4614f25832e802bd2932d72629ac544e0db3c0b4dce6072b3b5537e9d5af3b0f"],["chunk_7fef166d094cae58c843f813","wiki/sources/inb-2027-anlage-4-10-data.md",32,"Seite 16","Anfrage als unbeantwortet betrachtet.\n\n3.5 Phase der â€žLate Path Requestsâ€œ\n\nâ€œLate Paths Requestsâ€œ beziehen sich auf KapazitÃ¤tsanfragen zum Jahresfahrplan, die innerhalb\n\ndes Zeitraums von X-7.5 bis X-2 an den C-OSS gerichtet werden.\n\nIm CID jedes Korridors ist angegeben, ob die MÃ¶glichkeit besteht â€žLate Path Requestsâ€œ\n\nabzugeben oder nicht.\n\nAuf den GÃ¼terverkehrskorridoren mit DB InfraGO AG gibt es kein Angebot von â€žLate Path\n\nRequestsâ€œ.\n\n3.5.1 Produkt\n\nDie KapazitÃ¤t fÃ¼r â€žLate Path Requestsâ€œ kann auf folgende Weise angeboten werden:\n\nA) Ebenso wie bei den PaPs, entweder speziell konstruierte Trassen fÃ¼r â€žLate Path Requestsâ€œ\n\noder PaPs, die nicht fÃ¼r den Jahresfahrplan verwendet wurden.\n\nB) Auf der Grundlage von KapazitÃ¤tslots. Die Slots werden pro Korridorabschnitt angezeigt\n\nund es wird die regulÃ¤re Laufzeit angegeben. Zur Bestellung von KapazitÃ¤ten fÃ¼r â€žLate\n\nPath Requestsâ€œ stehen in PCS Korridorabschnitte ohne Zeitangaben zur VerfÃ¼gung. Der\n\nZugangsberechtigte kann seine individuell gewÃ¼nschte(n) Abfahrts- und/oder\n\nAnkunftszeit(en), Feeder- und Outflowrasse(n) sowie den Ausgangspunkt fÃ¼r die\n\nKonstruktion angeben. Die Angaben sollten die angegebenen Standard-Laufzeiten\n\neinhalten.\n\nDie KapazitÃ¤t â€žLate Path Requestsâ€œ muss Ã¼ber PCS entweder auf die gleiche Weise wie fÃ¼r\n\nPaPs oder durch Nutzung von KapazitÃ¤tsslots in PCS beantragt werden.\n\n16/22",187,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":16,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"faac2784adcd42679ea7e8ef8a38c258eff3eea3f8f225ef672307cbac8da9a8\",\"source_version_id\":\"sv_a0e42b2e610ee4ac2ff4558f\"}","d18906e5b12c134411d3b60f47348a7aa4bdef3e58080371023a2e2356970966"],["chunk_bbdb7e1362e2c7eb5165afad","wiki/sources/inb-2027-anlage-4-10-data.md",33,"Seite 17","Wenn der Korridor die MÃ¶glichkeit bietet, â€žLate Path Requestsâ€œ zu bestellen, wird im CID dieses\n\nKorridors angegeben, welche der oben genannten Varianten verwendet wird.\n\n3.5.2 â€žMultiple corridor pathsâ€œ (Korridortrassen, die auf mehreren Korridoren liegen)\n\nEs ist mÃ¶glich, dass sich KapazitÃ¤tsanfragen auf mehr als einen Korridor beziehen, wenn\n\nKapazitÃ¤t angeboten wird. Siehe 3.4.4.\n\n3.5.3 â€žLate Path Requestsâ€œ auf sich Ã¼berschneidenden Abschnitten\n\nSiehe 3.4.5.\n\nDie Beschreibung der gemeinsamen Angebote auf den sich Ã¼berschneidenden Abschnitten ist\n\nauf einer Karte in Anhang 4C des CID fÃ¼r jeden Korridor zu finden, sofern zutreffend.\n\n3.5.4 Bearbeitung von Anmeldungen\n\nDer C-OSS empfÃ¤ngt und sammelt alle Trassenanmeldungen, die Ã¼ber PCS gestellt werden.\n\n3.5.5 FÃ¼hrendes Tool fÃ¼r â€žLate Path Requestsâ€œ\n\nZugangsberechtigte, die â€žLate Path Requestsâ€œ an den C-OSS senden, mÃ¼ssen PCS\n\nverwenden. Im Rahmen des Konstruktionsprozesses kann das nationale Tool dem\n\nZugangsberechtigten zusÃ¤tzliche Informationen anzeigen.\n\nDie folgende Matrix zeigt fÃ¼r jeden Prozessschritt, welches Tool als fÃ¼hrendes Tool angesehen\n\nwird.\n\ne s a h P g n u d le m n A X s ib 5 X ,7 ( - - ) 2 e m h a n k c Ã¼ R X s ib X ) 8 2 ( - - to b e g n A 5 X 2 1 ( - ) . z n a tp e z k A X s ib 1 ( - ) g n u r e d n Ã„ B Z h c r u d g n u r e d n Ã„ U IE h c r u d g n u r e in r o tS\n\nFÃ¼hrendes\n\nPCS PCS PCS PCS pathOS pathOS pathOS\n\nTool\n\n3.5.6 ÃœberprÃ¼fung der AntrÃ¤ge\n\nDer C-OSS prÃ¼ft alle Anmeldungen wie in 3.4.9 beschrieben.\n\n3.5.7 Vorbuchung\n\nDer C-OSS koordiniert das Angebot mit den betroffenen IMs/ABs oder anderen C-OSS, falls\n\nerforderlich, nach der Regel \"wer zuerst kommt, mahlt zuerst\".\n\n3.5.8 Ausarbeitung der Trasse\n\nIn der Phase der Trassenausarbeitung werden die IMs/ABs â€“ soweit betroffen - das â€žLate Pathâ€œ",326,"{\"canonical_url\":null,\"normalized_sha256\":\"e2f2f3e204be8d87bfb3fb94b6634a28c60bae99ed4b4d45628850b34ae49201\",\"page\":17,\"source_id\":\"src_15b7c23aaedaa988dfc9\",\"source_sha256\":\"